const ORDEN = ["entrada", "inicio_almuerzo", "fin_almuerzo", "salida"];
const EVENT_LABELS = { entrada:"Entrada", inicio_almuerzo:"Inicio Almuerzo", fin_almuerzo:"Fin Almuerzo", salida:"Salida", omitido:"No registrado" };
const EVENT_COLORS = { entrada:C.green, inicio_almuerzo:C.amber, fin_almuerzo:C.blue, salida:C.red, omitido:C.red };

// ── Fechas Colombia ───────────────────────────────────────────────────────────
const toColombiaDate = (d = new Date()) => new Date(d.toLocaleString("en-US", { timeZone: "America/Bogota" }));
const fmt = (d) => { const c = toColombiaDate(d); return `${c.getFullYear()}-${String(c.getMonth()+1).padStart(2,"0")}-${String(c.getDate()).padStart(2,"0")}`; };
const fmtTime = (d) => { const c = toColombiaDate(d); return `${String(c.getHours()).padStart(2,"0")}:${String(c.getMinutes()).padStart(2,"0")}`; };
const todayStr = fmt(new Date());
// Supabase devuelve como máximo 1000 filas por consulta — si una tabla pasa de ahí y se pide con
// .select("*") a secas, las que sobran se pierden EN SILENCIO (ventas sin sus renglones/medios de
// pago, turnos faltantes, etc.). Esta función trae la tabla completa pidiendo de a 1000 filas
// (orden estable: el que se pida + id) hasta que ya no queden. Si algo falla en la paginación,
// cae a la consulta simple de antes para no dejar la app sin datos.
const traerTodo = async (tabla, orden = []) => {
  const PAGINA = 1000;
  let todas = [];
  for (let desde = 0; ; desde += PAGINA) {
    let q = supabase.from(tabla).select("*");
    orden.forEach(([col, asc]) => { q = q.order(col, { ascending: asc }); });
    q = q.order("id", { ascending: true }).range(desde, desde + PAGINA - 1);
    const { data, error } = await q;
    if (error) {
      let simple = supabase.from(tabla).select("*");
      orden.forEach(([col, asc]) => { simple = simple.order(col, { ascending: asc }); });
      return await simple;
    }
    todas = todas.concat(data || []);
    if (!data || data.length < PAGINA) break;
  }
  return { data: todas, error: null };
};
const fmtFechaHora = (iso) => iso ? new Date(iso).toLocaleString("es-CO", { day:"numeric", month:"short", year:"numeric", hour:"2-digit", minute:"2-digit" }) : "—";
// Días de calendario entre dos fechas "YYYY-MM-DD" (fechaFin - fechaIni)
const diasEntre = (fechaIni, fechaFin) => Math.round((new Date(fechaFin+"T00:00:00") - new Date(fechaIni+"T00:00:00")) / 86400000);

// ── Puntualidad ───────────────────────────────────────────────────────────────
// Los horarios esperados de entrada viven en la tabla `turnos_horarios` (editable desde
// Turnos ▸ Administrar ▸ Horarios), versionados por fecha de vigencia — así un cambio de
// horario aplica hacia adelante sin alterar cómo se evaluaron los registros pasados.
// Cada fila es de una "familia" de turno (T1, T2, T3, T4, TOF — la parte que comparten
// UT1/JT1/CT1, etc.) y puede ser genérica (tienda_id null, aplica a todas las tiendas) o
// específica de una tienda (ej. Chipichape T1 entra 1 hora antes que las demás T1).
const familiaDeTurno = (shift) => {
  if (!shift) return null;
  if (shift.toUpperCase().includes("TOF")) return "TOF";
  const match = shift.match(/T(\d)/i);
  return match ? `T${match[1]}` : null;
};

const getExpectedEntry = (shift, date, store, turnosHorarios) => {
  const familia = familiaDeTurno(shift);
  if (!familia) return null;
  const mejor = filaHorarioVigente(familia, store, turnosHorarios, date);
  if (!mejor) return null;
  const dow = new Date(date + "T12:00:00").getDay(); // 0=dom,1=lun,...,5=vie,6=sab
  const isVS = dow === 5 || dow === 6;
  const hhmm = isVS ? mejor.entrada_vs : mejor.entrada_lj;
  if (!hhmm) return null;
  const [h, m] = hhmm.split(":").map(Number);
  return h*60+m;
};

// `entradaCustom` ("HH:MM") anula el horario estándar del turno SOLO para ese día/persona —
// se usa para autorizaciones puntuales (ej. entrar más tarde un día por una jornada reducida)
// sin tener que crear un turno nuevo. Viene de `turnos_asignaciones.entrada_custom`.
const calcPuntualidad = (entryTime, shift, date, store, turnosHorarios, entradaCustom) => {
  if (!entryTime) return null;
  let expected;
  if (entradaCustom) {
    const [h, m] = entradaCustom.split(":").map(Number);
    expected = h*60+m;
  } else {
    expected = getExpectedEntry(shift, date, store, turnosHorarios);
  }
  if (expected === null || expected === undefined) return null;
  const [h, m] = entryTime.split(":").map(Number);
  const diff = (h * 60 + m) - expected;
  if (diff <= 5) return { puntual: true, diff: 0 };
  return { puntual: false, diff };
};
// Rango de horario esperado ("11:30am–8:00pm") para mostrar junto a la puntualidad — así se ve
// a qué hora debía entrar y hasta qué hora le tocaba trabajar ese día, sin tener que ir a
// consultar la malla de Turnos aparte. Respeta horarios especiales del día (entrada_custom /
// salida_custom) igual que calcPuntualidad.
const getExpectedRange = (shift, date, store, turnosHorarios, entradaCustom, salidaCustom) => {
  const familia = familiaDeTurno(shift);
  const fila = filaHorarioVigente(familia, store, turnosHorarios, date);
  const dow = new Date(date + "T12:00:00").getDay();
  const isVS = dow === 5 || dow === 6;
  const entradaStd = fila ? (isVS ? fila.entrada_vs : fila.entrada_lj) : null;
  const salidaStd = fila ? (isVS ? fila.salida_vs : fila.salida_lj) : null;
  const entrada = entradaCustom || entradaStd;
  const salida = salidaCustom || salidaStd;
  if (!entrada && !salida) return null;
  return `${fmtHora12(entrada)}–${fmtHora12(salida)}`;
};

// Cuánto se pasó (o le sobró) del tiempo de almuerzo permitido — comparando "fin_almuerzo" real
// contra "inicio_almuerzo" real, contra los 60 minutos de almuerzo que tiene todo el mundo (igual
// para todos los turnos y tiendas por ahora). Positivo = se demoró más de la hora, negativo =
// volvió antes de que se cumpliera. Se usa para el "+12"/"-4" chiquito junto a la hora de
// Fin Almuerzo, para que se note de un vistazo si alguien se está pasando del tiempo.
const DURACION_ALMUERZO_MIN = 60;
const calcDesvioAlmuerzo = (inicioTime, finTime) => {
  if (!inicioTime || !finTime) return null;
  const [h1, m1] = inicioTime.split(":").map(Number);
  const [h2, m2] = finTime.split(":").map(Number);
  return (h2*60+m2) - (h1*60+m1) - DURACION_ALMUERZO_MIN;
};

// ── Junta Admin — rotación del Monitor ───────────────────────────────────────
// El Monitor rota cada mes entre los líderes, en el orden de la lista
// (se edita desde la pestaña Equipo y perfiles, con las flechas ▲▼).
// Arranca oficialmente en agosto de 2026 — el primero de la lista es monitor ese mes.
const JUNTA_ROTATION_EPOCH = "2026-08-01";
const mesesEntre = (ini, fin) => {
  const a = new Date(ini + "T12:00:00"), b = new Date(fin + "T12:00:00");
  return (b.getFullYear() - a.getFullYear()) * 12 + (b.getMonth() - a.getMonth());
};
const getMonitorDeMes = (lideres, anio, mes) => {
  if (!lideres.length) return null;
  const ordenados = [...lideres].sort((x, y) => (x.orden ?? 999) - (y.orden ?? 999));
  const fechaMes = `${anio}-${String(mes + 1).padStart(2, "0")}-01`;
  const ciclo = Math.max(0, mesesEntre(JUNTA_ROTATION_EPOCH, fechaMes));
  return ordenados[ciclo % ordenados.length];
};
const getMonitorActual = (lideres) => {
  const hoy = toColombiaDate();
  return getMonitorDeMes(lideres, hoy.getFullYear(), hoy.getMonth());
};
// Compara nombres sin importar mayúsculas/tildes/espacios — para saber si la cuenta que inició
// sesión es la misma persona que el líder configurado como Monitor de turno (no hay un vínculo
// directo entre "líderes" de la Junta y las cuentas de usuario, así que se compara por nombre).
const normalizarNombre = (s) => (s||"").trim().toLowerCase();
// ¿Este líder de la Junta ES esta cuenta? Si el líder ya tiene una cuenta enlazada (columna
// `usuario_id` de junta_lideres — master la asigna en Permisos → Monitor y líderes) manda ese
// enlace y el nombre ya no importa. Mientras no tenga enlace se sigue comparando por nombre, como
// siempre, para que nada cambie el día que se estrena esto (pedido de Santiago, nov 2026).
const liderEsDeUsuario = (lider, user) => {
  if (!lider || !user) return false;
  if (lider.usuario_id) return String(lider.usuario_id) === String(user.id);
  if (!lider.nombre || !user.name) return false;
  // sensitivity:"base" ignora mayúsculas y tildes, así que "José" y "jose" cuentan como el mismo nombre.
  return normalizarNombre(lider.nombre).localeCompare(normalizarNombre(user.name), "es", { sensitivity:"base" }) === 0;
};
const esMonitorActual = (user, lideres) => liderEsDeUsuario(getMonitorActual(lideres), user);
// Suma (o resta, con n negativo) n días de calendario a una fecha "aaaa-mm-dd".
const sumarDias = (fechaStr, n) => fmt(new Date(new Date(fechaStr+"T12:00:00").getTime() + n*86400000));
// Fechas (aaaa-mm-dd) de todos los martes de un mes calendario dado.
const martesDelMes = (anio, mes) => {
  const dias = [];
  const d = new Date(anio, mes, 1, 12);
  while (d.getMonth() === mes) {
    if (d.getDay() === 2) dias.push(fmt(d));
    d.setDate(d.getDate() + 1);
  }
  return dias;
};
// Rediseño (21 sept): las semanas de la Junta corren de LUNES a DOMINGO — no importa qué día de
// esa semana se haga la reunión, la tarea sigue vigente toda la semana. `fecha_estimada` se sigue
// guardando como el MARTES de la semana objetivo (mismo formato de siempre, para no migrar datos
// viejos — y porque el martes sigue siendo el que decide de qué mes/Monitor es esa semana, ver
// getMonitorDeMes/martesDelMes), pero el plazo real ahora corre hasta el DOMINGO de esa semana
// (martes + 5 días) — antes vencía justo en el martes.
const domingoDeLaSemana = (martesStr) => sumarDias(martesStr, 5);
const tareaVencidaNoRealizada = (t) => !t.completado && !!t.fecha_estimada && todayStr > domingoDeLaSemana(t.fecha_estimada);
// Al marcar una tarea como hecha hay 5 minutos de gracia para desmarcarla por si fue un error
// (típico durante la reunión en vivo). Pasado ese tiempo queda fija.
const GRACIA_DESMARCAR_MS = 5 * 60 * 1000;
const dentroDeGracia = (t) => !!t.completado_en && (Date.now() - new Date(t.completado_en).getTime()) < GRACIA_DESMARCAR_MS;
// Rediseño (21 sept): se quitó toda la regla de "congelamiento" por mes (semana de gracia, mes
// anterior de solo lectura, etc.) — el monitor y el master pueden gestionar cualquier tarea activa
// o reabrir cualquier vencida, sin importar de qué mes sea. En su lugar, cada fin de mes se guarda
// una foto fija de los indicadores (ver junta_indicadores_congelados / JuntaIndicadoresTab) que ya
// no se recalcula después, así que reabrir una tarea vieja nunca altera un indicador ya publicado.
// Mes al que se le "atribuye" una tarea ya cerrada, para efectos de indicadores — no es el mes en
// que se asignó (c.semana), sino el mes en que de verdad se resolvió: para una cumplida, el mes en
// que se marcó (completado_en); para una vencida, el mes en que venció (fecha_estimada, que es
// cuando pasa a vencida sola, sin que nadie la marque). Así una tarea de la última semana de un mes
// que se revisa ya en el mes siguiente (o con el Monitor nuevo) cuenta para el mes en que en
// realidad se cumplió o venció, no para el mes en que se creó — "lo que pasó ya pasó". Si faltan
// esos campos por datos antiguos, se usa `semana` como respaldo para no perder el dato.
const mesDeCierre = (t) => {
  if (t.completado) return (t.completado_en ? fmt(new Date(t.completado_en)) : t.semana || "").slice(0,7) || null;
  if (tareaVencidaNoRealizada(t)) return (t.fecha_estimada || t.semana || "").slice(0,7) || null;
  return null; // sigue activa — todavía no se cierra, no cuenta para ningún mes.
};
// Una tarea reabierta indefinidamente antes de vencerse nunca llegaba a contar como incumplida en
// ningún mes — el reloj se reiniciaba cada vez, así que terminaba viéndose igual de "cumplida" que
// una que se hizo bien a la primera. Esto usa el historial que YA se guarda en cada reapertura
// (reaperturas: fecha_anterior/fecha_nueva/en) para saber si, en el momento exacto de reabrirla, la
// tarea YA estaba vencida (pasado el domingo de su plazo anterior). Si pasó al menos una vez, la
// tarea "tuvo una reapertura tardía" — aunque termine cumplida, no fue a tiempo.
const tuvoReaperturaTardia = (t) => (t.reaperturas||[]).some(r => r.fecha_anterior && r.en && fmt(new Date(r.en)) > domingoDeLaSemana(r.fecha_anterior));
// Cumplida "a tiempo" = cumplida Y nunca tuvo que reabrirse después de estar vencida.
const cumplidaATiempo = (t) => !!t.completado && !tuvoReaperturaTardia(t);
// Indicadores de un mes: sesiones registradas (martes con al menos una tarea) y % de tareas completadas.
// "Sesiones" y "tareas asignadas" se cuentan por `semana` (cuántas reuniones hubo y cuántas tareas
// salieron de ellas ese mes) — eso no cambió. El % de cumplimiento, en cambio, se calcula sobre las
// tareas CERRADAS EN ese mes (ver mesDeCierre arriba), vengan de la semana que vengan — una tarea
// todavía activa (no completada, dentro de plazo) no cuenta ni a favor ni en contra todavía, porque
// todavía puede completarse. Contarla de una vez castigaba el % de más, de forma injusta.
// "activas" (el aviso de "X todavía activas, no cuentan aún") solo tiene sentido para el MES EN
// CURSO — una vez arranca el mes del siguiente Monitor, ese mes ya quedó atrás: cualquier tarea
// suya que siga sin cerrar no va a contar para ese mes nunca (va a contar para el mes en que
// realmente se cierre, sea cual sea — ver mesDeCierre), así que ya no tiene caso mostrarla como
// "pendiente de este mes". Por eso en un mes ya pasado siempre da 0.
const statsDelMes = (compromisos, anio, mes) => {
  const martes = martesDelMes(anio, mes);
  const mesStr = `${anio}-${String(mes+1).padStart(2,"0")}`;
  const tareas = compromisos.filter(c => martes.includes(c.semana));
  const sesiones = new Set(tareas.map(t => t.semana)).size;
  const cerradas = compromisos.filter(c => mesDeCierre(c) === mesStr);
  const completadas = cerradas.filter(t => t.completado).length;
  // completadasATiempo es un subconjunto de completadas: de lo cumplido, cuánto se cumplió SIN
  // haber tenido que reabrirse después de vencido — ver cumplidaATiempo/tuvoReaperturaTardia arriba.
  // pct (cumplimiento total) no cambia; pctATiempo es el nuevo dato, más exigente.
  const completadasATiempo = cerradas.filter(cumplidaATiempo).length;
  const hoy = toColombiaDate();
  const esMesEnCurso = anio===hoy.getFullYear() && mes===hoy.getMonth();
  const activas = esMesEnCurso ? tareas.filter(t => !t.completado && !tareaVencidaNoRealizada(t)).length : 0;
  const pct = cerradas.length ? Math.round((completadas / cerradas.length) * 100) : null;
  const pctATiempo = cerradas.length ? Math.round((completadasATiempo / cerradas.length) * 100) : null;
  return { totalMartes: martes.length, sesiones, totalTareas: tareas.length, completadas, completadasATiempo, totalCerradas: cerradas.length, activas, pct, pctATiempo };
};
// Cumplimiento de tareas, pero desglosado por cada líder — no todos cargan el mismo peso ni la
// misma cantidad de tareas, así que el % se calcula individualmente (completadas ÷ cerradas). Igual
// que en statsDelMes, "total" (cantidad asignada) sigue por semana, pero el cumplimiento (cerradas/
// completadas/pct) se atribuye al mes real de cierre.
const statsPorLiderDelMes = (compromisos, lideres, anio, mes) => {
  const martes = martesDelMes(anio, mes);
  const mesStr = `${anio}-${String(mes+1).padStart(2,"0")}`;
  const tareas = compromisos.filter(c => martes.includes(c.semana));
  const cerradasMes = compromisos.filter(c => mesDeCierre(c) === mesStr);
  return lideres
    .map(l => {
      const deLider = tareas.filter(t => t.lider_id === l.id);
      const cerradasLider = cerradasMes.filter(t => t.lider_id === l.id);
      const completadas = cerradasLider.filter(t => t.completado).length;
      const completadasATiempo = cerradasLider.filter(cumplidaATiempo).length;
      const pct = cerradasLider.length ? Math.round((completadas / cerradasLider.length) * 100) : null;
      const pctATiempo = cerradasLider.length ? Math.round((completadasATiempo / cerradasLider.length) * 100) : null;
      return { lider: l, total: deLider.length, completadas, completadasATiempo, totalCerradas: cerradasLider.length, pct, pctATiempo };
    })
    .filter(x => x.total > 0 || x.totalCerradas > 0)
    .sort((a,b) => (a.lider.nombre||"").localeCompare(b.lider.nombre||""));
};
// Indicadores de la Junta: un solo color (azul) para cualquier % cumplido, sin el semáforo
// rojo/ámbar/verde — ahí no se busca presionar, solo mostrar el dato. La única señal que cambia
// con el % es qué tan "lleno" se ve el badge — ver intensidadPct, usada con el prop `intensity`
// de Badge.
const colorCumplimientoTexto = (pct) => pct===null || pct===undefined ? C.textMuted : C.blue;
const intensidadPct = (pct) => pct===null || pct===undefined ? 0.15 : Math.max(0, Math.min(1, pct/100));
// IDC de Ventas: aquí sí se busca presión visual sobre asesores/tiendas, así que se queda el
// semáforo clásico. Sin datos = gris. 100% o más = verde. 70-99% = ámbar. Menos de 70% = rojo.
const colorSemaforoIDC = (pct) => pct===null || pct===undefined ? C.textMuted : pct>=100 ? C.green : pct>=70 ? C.amber : C.red;
const medalla = (idx) => idx===0?"🥇":idx===1?"🥈":idx===2?"🥉":`${idx+1}.`;
// Barra de cumplimiento reutilizable (misma idea que la burbuja "Meta de hoy"): el 100% real casi
// nunca coincide con el ancho completo de la barra — la escala se ajusta a quien va más adelante
// en el grupo (mínimo 100%, o más si alguien ya se pasó de la meta), y una marca blanca sutil
// señala exactamente dónde cae el 100% dentro de esa escala compartida. Así, si nadie ha llegado
// a la meta, la barra de nadie se ve "llena" todavía; y si alguien se pasa (105%, 123%...), TODAS
// las barras del grupo se reacomodan a esa nueva escala para que se sigan pudiendo comparar entre
// sí de un vistazo — quien manda la escala es quien va ganando.
const BarraCumplimiento = ({ pctRaw, escalaMax, color, width=110, height=9, solido }) => {
  const escala = Math.max(100, escalaMax||100);
  const anchoBarra = Math.max(0, Math.min(100, ((pctRaw||0)/escala)*100));
  const marca100Pct = (100/escala)*100;
  return (
    <span style={{ width, flexShrink:0, height, borderRadius:height/2, background:C.surfaceHover, overflow:"hidden", position:"relative", display:"inline-block" }}>
      <span style={{ position:"absolute", inset:0, width:`${anchoBarra}%`, borderRadius:height/2, background:solido ? color : `linear-gradient(90deg, ${C.blue}, ${color})`, transition:"width 0.5s cubic-bezier(.34,1.2,.5,1)" }}/>
      {marca100Pct<100 && <span style={{ position:"absolute", top:0, bottom:0, left:`${marca100Pct}%`, width:1, background:"rgba(26,59,82,0.35)" }}/>}
    </span>
  );
};
// Fila de un ranking (tiendas o asesores por cumplimiento): medalla + nombre + barra de
// cumplimiento + "$vendido / $meta" + badge de %. En celular un nombre largo (ej. "OZEN Jardín
// Plaza", "Fernanda Caicedo") no cabía junto a los números y el badge sin cortarse (con "...") o
// amontonarse — así que en celular se parte en dos renglones: nombre completo arriba (con el
// badge, que ocupa poco espacio), números abajo, indentados bajo el nombre. Nunca se trunca el
// nombre (se deja hacer wrap si hace falta) — mejor una fila más alta que un nombre invisible.
// `escalaMax` (el idc más alto del grupo completo) lo calcula quien arma el ranking, para que
// todas las barras de una misma lista compartan la misma escala. Centralizado acá para que
// cualquier ranking nuevo que se agregue después reuse este comportamiento en vez de repetir el
// problema.
const RankingRow = ({ idx, nombre, extra, sinServicios, meta, idc, isMobile, escalaMax }) => (
  <div style={{ display:"flex", flexDirection:isMobile?"column":"row", alignItems:isMobile?"stretch":"center", gap:isMobile?4:10, background:idx<3?`${C.gold}0d`:C.surfaceAlt, border:`1px solid ${idx<3?C.gold:C.border}`, borderRadius:8, padding:"9px 12px" }}>
    <div style={{ display:"flex", alignItems:"center", gap:10, minWidth:0 }}>
      <div style={{ fontFamily:font.body, fontSize:idx<3?16:13, width:28, textAlign:"center", flexShrink:0 }}>{medalla(idx)}</div>
      <div style={{ flex:1, display:"flex", alignItems:"center", gap:6, minWidth:0 }}>
        <span style={{ fontFamily:font.body, fontSize:13, color:C.text, fontWeight:600 }}>{nombre}</span>
        {extra}
      </div>
      {isMobile && <Badge color={colorSemaforoIDC(idc)} sm>{idc}%</Badge>}
    </div>
    <div style={{ display:"flex", alignItems:"center", justifyContent:isMobile?"space-between":"flex-end", gap:10, paddingLeft:isMobile?38:0 }}>
      <BarraCumplimiento pctRaw={idc} escalaMax={escalaMax} color={colorSemaforoIDC(idc)} width={isMobile?80:110} height={9}/>
      <span style={{ fontFamily:font.mono, fontSize:12, color:C.textMuted, whiteSpace:"nowrap" }}>{fmtCOP(sinServicios)} / {fmtCOP(meta)}</span>
      {!isMobile && <Badge color={colorSemaforoIDC(idc)} sm>{idc}%</Badge>}
    </div>
  </div>
);
// Devuelve el martes de la semana de una fecha (o la fecha misma si ya es martes)
const martesDeSemana = (dateStr) => {
  const d = new Date(dateStr + "T12:00:00");
  const dow = d.getDay(); // 0=dom,1=lun,2=mar...
  const delta = (dow - 2 + 7) % 7;
  d.setDate(d.getDate() - delta);
  return fmt(d);
};

// ── Hook de inactividad ───────────────────────────────────────────────────────
function useInactivityLogout(onTimeout, minutos = 5) {
  useEffect(() => {
    let timer;
    const reset = () => {
      clearTimeout(timer);
      timer = setTimeout(onTimeout, minutos * 60 * 1000);
    };
    const eventos = ["mousedown","keydown","touchstart","scroll"];
    eventos.forEach(ev => window.addEventListener(ev, reset));
    reset();
    return () => {
      clearTimeout(timer);
      eventos.forEach(ev => window.removeEventListener(ev, reset));
    };
  }, [onTimeout, minutos]);
}

// Exige mantener presionado (mouse o dedo) durante un rato antes de ejecutar la acción — sin
// ningún aviso visual de que hay que hacerlo, a propósito. Un clic/toque rápido no hace nada.
function useLongPress(callback, duracionMs = 700) {
  const timerRef = useRef(null);
  const empezar = () => { timerRef.current = setTimeout(callback, duracionMs); };
  const cancelar = () => { if (timerRef.current) clearTimeout(timerRef.current); timerRef.current = null; };
  return { onMouseDown: empezar, onMouseUp: cancelar, onMouseLeave: cancelar, onTouchStart: empezar, onTouchEnd: cancelar, onTouchCancel: cancelar };
}

// ── Responsive ────────────────────────────────────────────────────────────────
function useIsMobile() {
  const [isMobile, setIsMobile] = useState(window.innerWidth < 768);
  useEffect(() => {
    const h = () => setIsMobile(window.innerWidth < 768);
    window.addEventListener("resize", h);
    return () => window.removeEventListener("resize", h);
  }, []);
  return isMobile;
}

// ── UI Primitives ─────────────────────────────────────────────────────────────
// `intensity` (0 a 1, opcional) controla qué tan lleno se ve el relleno/borde del badge, sin
// cambiar el color en sí ni el texto (siempre sólido y legible) — se usa para indicadores de %
// donde se quiere una señal suave de "más alto = más lleno" en vez de cambiar de color entero
// (rojo/ámbar/verde), que se sentía como un semáforo castigador. Si no se pasa, se comporta igual
// que antes (relleno fijo).
const alphaHex = (n) => Math.max(0, Math.min(255, Math.round(n))).toString(16).padStart(2, "0");
const Badge = ({ color, children, sm, title, intensity }) => {
  const bgAlpha = intensity==null ? 32 : (14 + intensity*46);
  const borderAlpha = intensity==null ? 64 : (35 + intensity*80);
  return (
    <span title={title} style={{ display:"inline-flex", alignItems:"center", padding: sm?"2px 8px":"3px 10px", borderRadius:99, fontSize:sm?10:11, fontWeight:600, background:`${color}${alphaHex(bgAlpha)}`, color, border:`1px solid ${color}${alphaHex(borderAlpha)}`, fontFamily:font.body, letterSpacing:"0.04em", textTransform:"uppercase", whiteSpace:"nowrap", cursor:title?"help":"default" }}>{children}</span>
  );
};

const Btn = ({ onClick, children, variant="primary", sm, disabled, full, style={} }) => {
  const [hov, setHov] = useState(false);
  const base = { display:"inline-flex", alignItems:"center", justifyContent:"center", gap:6, padding:sm?"7px 14px":"11px 20px", borderRadius:10, border:"none", cursor:disabled?"not-allowed":"pointer", fontSize:sm?12:13.5, fontWeight:600, fontFamily:font.body, letterSpacing:"0.01em", transition:"all 0.15s", opacity:disabled?0.4:1, width:full?"100%":undefined };
  const styles = {
    // Propuesta A: tres niveles de botón — principal en Sombra con texto Tinta (uno por pantalla,
    // lo más importante), secundario con borde Base (acciones de apoyo) y enlaces de texto.
    primary: { background:hov?C.gold:C.goldDark, color:C.tinta },
    ghost:   { background:hov?"rgba(38,93,127,0.07)":"transparent", color:C.gold, border:`1px solid rgba(38,93,127,0.4)` },
    danger:  { background:hov?"rgba(231,76,60,0.22)":C.redDim, color:C.red, border:`1px solid ${C.red}44` },
    success: { background:hov?"rgba(46,204,113,0.22)":C.greenDim, color:C.green, border:`1px solid ${C.green}44` },
  };
  return <button style={{...base,...styles[variant],...style}} onClick={disabled?undefined:onClick} onMouseEnter={()=>setHov(true)} onMouseLeave={()=>setHov(false)}>{children}</button>;
};

// ── "Ver como" (Permisos, Fase 4) ─────────────────────────────────────────────
// Master puede ver la app tal como la ve otra persona o rol, sin cerrar sesión. Mientras dure,
// NADA se guarda: toda escritura a la base (insert/update/delete/upsert), a los archivos (fotos,
// PDFs) y a las funciones del servidor (avisos push) se responde con un error y no sale de aquí.
// Así un clic por error no registra nada a nombre de otra persona.
let permModoVerComo = false;
const permVerComoActivar = (v) => { permModoVerComo = !!v; };
const VER_COMO_NO_GUARDA = { data:null, error:{ message:"Estás en «Ver como»: nada se guarda. Sal de «Ver como» para hacer cambios." } };
const verComoNulo = () => { const pr = new Proxy(function(){}, { get:(_, k) => k==="then" ? (ok, ko) => Promise.resolve(VER_COMO_NO_GUARDA).then(ok, ko) : () => pr, apply:() => pr }); return pr; };
try {
  const fromOrig = supabase.from.bind(supabase);
  supabase.from = (t) => { const q = fromOrig(t); if (permModoVerComo) ["insert","update","delete","upsert"].forEach(m => { q[m] = () => verComoNulo(); }); return q; };
  if (supabase.storage && supabase.storage.from) {
    const stFrom = supabase.storage.from.bind(supabase.storage);
    supabase.storage.from = (b) => { const q = stFrom(b); if (permModoVerComo) ["upload","update","remove","move","copy"].forEach(m => { q[m] = () => Promise.resolve(VER_COMO_NO_GUARDA); }); return q; };
  }
  let o = supabase, dFn = null;
  while (o && !dFn) { dFn = Object.getOwnPropertyDescriptor(o, "functions"); o = Object.getPrototypeOf(o); }
  if (dFn && dFn.get) Object.defineProperty(supabase, "functions", { configurable:true, get() { const f = dFn.get.call(supabase); if (permModoVerComo) f.invoke = () => Promise.resolve(VER_COMO_NO_GUARDA); return f; } });
} catch(e) { console.warn("Ver como: no se pudo instalar el bloqueo de escrituras", e); }
// Franja de arriba mientras se está en "Ver como".
const BandaVerComo = ({ u, onSalir }) => (
  <div style={{ display:"flex", alignItems:"center", gap:10, flexWrap:"wrap", padding:"8px 14px", background:C.amber, color:"#fff", fontFamily:font.body, fontSize:13, fontWeight:600, flexShrink:0 }}>
    <Icon n="user" s={15}/>
    <span style={{ flex:1, minWidth:180 }}>Viendo como <b>{u.name}</b> · {ROLE_LABEL[u.role]||u.role} · nada de lo que hagas se guarda</span>
    <button onClick={onSalir} style={{ background:"#fff", color:C.amber, border:"none", borderRadius:99, padding:"5px 14px", fontFamily:font.body, fontSize:12.5, fontWeight:700, cursor:"pointer" }}>Salir de «Ver como»</button>
  </div>
);

// ── Confirmación propia de la app ────────────────────────────────────────────────
// Reemplaza a window.confirm en TODA la app (pedido de Santiago, nov 2026): en algunos navegadores
// la ventanita del navegador no sale y la acción seguía de largo sin preguntar — borraba sin
// confirmar. Uso, dentro de una función async:  if(!await confirmar("¿Borrar esto?")) return;
// Si por alguna razón el recuadro no está montado, cae a la ventanita del navegador de siempre.
let confirmarHost = null;
const confirmar = (texto) => confirmarHost ? new Promise(res => confirmarHost({ texto, res })) : Promise.resolve(window.confirm(texto));
// Igual, pero para lo más delicado: hay que ESCRIBIR una palabra para poder continuar (reemplaza a
// window.prompt). Uso:  if(!await confirmarEscribiendo("…Escribe BORRAR para confirmar.", "BORRAR")) return;
const confirmarEscribiendo = (texto, palabra) => confirmarHost ? new Promise(res => confirmarHost({ texto, res, palabra })) : Promise.resolve(window.prompt(texto) === palabra);
function ConfirmacionGlobal() {
  const [c, setC] = useState(null);
  const [escrito, setEscrito] = useState("");
  useEffect(() => {
    const host = (nuevo) => { setEscrito(""); setC(prev => { if (prev) prev.res(false); return nuevo; }); };
    confirmarHost = host;
    return () => { if (confirmarHost === host) confirmarHost = null; };
  }, []);
  useEffect(() => {
    if (!c) return;
    const tecla = (e) => { if (e.key === "Escape") { c.res(false); setC(null); } };
    window.addEventListener("keydown", tecla);
    return () => window.removeEventListener("keydown", tecla);
  }, [c]);
  if (!c) return null;
  // Con palabra: solo deja continuar cuando lo escrito coincide (sin importar mayúsculas ni espacios).
  const listo = !c.palabra || escrito.trim().toUpperCase() === c.palabra.toUpperCase();
  const responder = (si) => { if (si && !listo) return; c.res(si); setC(null); };
  return createPortal(
    <div onClick={()=>responder(false)} style={{ position:"fixed", inset:0, zIndex:5000, background:"rgba(26,59,82,0.38)", display:"flex", alignItems:"center", justifyContent:"center", padding:16 }}>
      <div onClick={e=>e.stopPropagation()} style={{ background:C.surface, borderRadius:14, border:`1px solid ${C.border}`, padding:"20px 22px", maxWidth:c.palabra?480:440, width:"100%", maxHeight:"86vh", overflowY:"auto", fontFamily:font.body }}>
        <div style={{ fontSize:15, fontWeight:700, color:C.text, marginBottom:8 }}>¿Seguro?</div>
        <div style={{ fontSize:13.5, color:C.textSub, lineHeight:1.5, marginBottom:c.palabra?12:18, whiteSpace:"pre-line" }}>{c.texto}</div>
        {c.palabra && (
          <input autoFocus value={escrito} onChange={e=>setEscrito(e.target.value)} onKeyDown={e=>{ if (e.key === "Enter") responder(true); }} placeholder={`Escribe ${c.palabra}`} autoComplete="off" autoCapitalize="characters" spellCheck={false}
            style={{ width:"100%", boxSizing:"border-box", background:C.surfaceAlt, border:`1px solid ${listo?C.green:C.border}`, borderRadius:9, padding:"10px 12px", color:C.text, fontSize:14, fontFamily:font.body, fontWeight:600, letterSpacing:"0.04em", outline:"none", marginBottom:18 }}/>
        )}
        <div style={{ display:"flex", gap:8, justifyContent:"flex-end" }}>
          <Btn onClick={()=>responder(false)} variant="ghost" sm>Cancelar</Btn>
          <Btn onClick={()=>responder(true)} variant="danger" sm disabled={!listo}>Sí, continuar</Btn>
        </div>
      </div>
    </div>, document.body);
}

// "Minimalista plano" — es el componente base con el que están armadas las fichas/burbujas de
// cada módulo (~55 pantallas), así que este único cambio se propaga a toda la app. Se probaron
// dos intentos con profundidad (vidrio esmerilado, luego sombra de elevación) y ninguno se notó
// bien o se sintió acertado — este va en la dirección opuesta a propósito: sin sombra, sin
// transparencia, sin intentar simular profundidad. Solo un fondo sólido y un borde discreto que
// define el contorno, dejando que el propio contenido sea lo que se note. Caja sigue siendo la
// única pantalla con su propio look a color (CajaCard, sin tocar).
const Card = ({ children, style={}, glow, p="20px" }) => (
  <div style={{
    background: C.surface,
    borderRadius: 14,
    border: `1px solid ${glow ? C.borderGold : C.border}`,
    boxShadow: "none",
    padding: p,
    ...style,
  }}>{children}</div>
);

// Envoltorio para desplegar/ocultar contenido con animación (menús, filas expandibles, "ver más").
// Usa el truco de grid-template-rows 0fr↔1fr: anima suavemente a la altura real del contenido sin
// tener que medirla con JS. El contenido solo se monta la primera vez que se abre (así una fila que
// nunca se despliega no gasta cómputo de más) pero se queda montado después para que el cierre
// también se vea animado, no de golpe.
function Collapse({ open, children }) {
  const [montado, setMontado] = useState(open);
  useEffect(()=>{ if(open) setMontado(true); }, [open]);
  return (
    <div className="ozen-collapse" style={{ gridTemplateRows: open ? "1fr" : "0fr" }}>
      <div style={{ overflow:"hidden", minHeight:0 }}>{montado ? children : null}</div>
    </div>
  );
}

// Campo de valor en pesos colombianos: mientras se escribe muestra $000.000,
// pero guarda (y entrega vía onChange) solo los dígitos, como los demás campos numéricos.
const CurrencyField = ({ label, value, onChange, placeholder, disabled, noMargin }) => {
  const digits = String(value||"").replace(/[^\d]/g,"");
  const mostrado = digits ? `$${Number(digits).toLocaleString("es-CO")}` : "";
  return (
    <div style={{ marginBottom: noMargin?0:14 }}>
      {label && <div style={{ fontSize:11, color:C.textMuted, fontFamily:font.body, marginBottom:5, textTransform:"uppercase", letterSpacing:"0.07em" }}>{label}</div>}
      <input
        type="text"
        inputMode="numeric"
        value={mostrado}
        onChange={e=>onChange(e.target.value.replace(/[^\d]/g,""))}
        placeholder={placeholder||"$0"}
        disabled={disabled}
        style={{ width:"100%", background:disabled?C.dark:C.surfaceAlt, border:`1px solid ${C.border}`, borderRadius:7, padding:"9px 11px", color:disabled?C.textMuted:C.text, fontSize:13, fontFamily:font.body, outline:"none", boxSizing:"border-box", cursor:disabled?"not-allowed":"text" }}
      />
    </div>
  );
};

const Field = ({ label, value, onChange, type="text", placeholder, options, disabled, multiline, rows=4, autoComplete }) => (
  <div style={{ marginBottom:14, minWidth:0 }}>
    {label && <div style={{ fontSize:11, color:C.textMuted, fontFamily:font.body, marginBottom:5, textTransform:"uppercase", letterSpacing:"0.07em" }}>{label}</div>}
    {options ? (
      <select value={value} onChange={e=>onChange(e.target.value)} disabled={disabled} style={{ width:"100%", minWidth:0, background:disabled?C.dark:C.surfaceAlt, border:`1px solid ${C.border}`, borderRadius:7, padding:"9px 11px", color:disabled?C.textMuted:C.text, fontSize:13, fontFamily:font.body, outline:"none", boxSizing:"border-box" }}>
        {/* El navegador dibuja el desplegable de <option> con su propio fondo (casi siempre
            blanco), no con el fondo oscuro del <select> — así que sin un color explícito acá el
            texto claro pensado para fondo oscuro (C.text) queda casi ilegible sobre ese blanco.
            Fijar background/color directo en cada <option> lo corrige en Chrome/Edge/Firefox. */}
        {options.map(o=><option key={o.value} value={o.value} style={{ background:C.surface, color:C.text }}>{o.label}</option>)}
      </select>
    ) : multiline ? (
      <textarea value={value} onChange={e=>onChange(e.target.value)} placeholder={placeholder} disabled={disabled} rows={rows} style={{ width:"100%", minWidth:0, background:disabled?C.dark:C.surfaceAlt, border:`1px solid ${C.border}`, borderRadius:7, padding:"9px 11px", color:disabled?C.textMuted:C.text, fontSize:13, fontFamily:font.body, outline:"none", boxSizing:"border-box", resize:"vertical", lineHeight:1.5 }} />
    ) : (
      // `minWidth:0` es necesario porque dentro de un grid/flex, un input (sobre todo
      // type="date") no se encoge por debajo de su ancho de contenido por defecto — eso hacía
      // que la casilla de Fecha se saliera por la derecha de su tarjeta en celular, aunque tenga
      // width:100%. WebkitAppearance:"none" en el de fecha quita el tamaño nativo extra que
      // agrega iOS Safari al calendario, que era la otra causa de que se viera más alto/ancho
      // que los demás campos.
      <input type={type} value={value} onChange={e=>onChange(e.target.value)} placeholder={placeholder} disabled={disabled} autoComplete={autoComplete} style={{ width:"100%", minWidth:0, background:disabled?C.dark:C.surfaceAlt, border:`1px solid ${C.border}`, borderRadius:7, padding:"9px 11px", color:disabled?C.textMuted:C.text, fontSize:13, fontFamily:font.body, outline:"none", boxSizing:"border-box", ...(type==="date"?{WebkitAppearance:"none", appearance:"none"}:{}) }} />
    )}
  </div>
);

// Texto que aparece al pasar el mouse (o al tocar, en celular) sobre una etiqueta — para
// explicaciones cortas (IDC, MDA) o avisos largos (términos del Flexipago) sin ocupar espacio fijo.
// clickOnly: en algunos dispositivos el hover titila o la nube sale cortada — con clickOnly
// se abre/cierra solo al dar clic, sin depender del hover.
const HoverTooltip = ({ label, labelStyle={}, width=280, align="left", clickOnly=false, bloque=false, children }) => {
  const [show, setShow] = useState(false);
  // `bloque`: el disparador ocupa todo el ancho disponible (para filas que deben estirarse).
  return (
    <span style={{ position:"relative", display:bloque?"block":"inline-block" }}>
      <span
        onMouseEnter={clickOnly?undefined:()=>setShow(true)}
        onMouseLeave={clickOnly?undefined:()=>setShow(false)}
        onClick={()=>setShow(s=>!s)}
        style={{ textDecoration:"underline dotted", textUnderlineOffset:3, cursor:"help", fontFamily:font.body, ...(bloque?{ display:"block" }:{}), ...labelStyle }}
      >{label}</span>
      {show && clickOnly && (
        // En clickOnly, además de volver a tocar el mismo ⓘ, dar clic en cualquier otra parte de
        // la pantalla también cierra la nube — sin esto, la única forma de cerrarla era encontrar
        // exactamente el mismo ícono, lo cual es incómodo sobre todo en celular.
        <div onClick={()=>setShow(false)} style={{ position:"fixed", inset:0, zIndex:79 }}/>
      )}
      {show && (
        <div style={{ position:"absolute", zIndex:80, top:"130%", [align]:0, width, maxWidth:"80vw", background:C.dark, border:`1px solid ${C.border}`, borderRadius:8, padding:"10px 12px", boxShadow:"0 6px 24px rgba(0,0,0,0.5)", textAlign:"left" }}>
          {children}
        </div>
      )}
    </span>
  );
};

const StatCard = ({ label, value, icon, color }) => (
  <Card style={{ display:"flex", alignItems:"center", gap:16 }}>
    <div style={{ width:44, height:44, borderRadius:10, background:`${color}18`, display:"flex", alignItems:"center", justifyContent:"center", fontSize:20, flexShrink:0 }}>{icon}</div>
    <div>
      <div style={{ fontFamily:font.mono, fontSize:24, fontWeight:700, color, lineHeight:1 }}>{value}</div>
      <div style={{ fontFamily:font.body, fontSize:11, color:C.textMuted, marginTop:3 }}>{label}</div>
    </div>
  </Card>
);

const Divider = () => <div style={{ height:1, background:C.border, margin:"12px 0" }} />;
// `middle` es opcional (nadie más lo usa hoy) — un hueco extra entre el título y `action` para
// widgets como EnTurnoIndicator, sin tocar el layout de las pantallas que no lo pasan.
const PageHeader = ({ title, subtitle, action, middle }) => (
  <div style={{ display:"flex", flexWrap:"wrap", alignItems:"flex-start", justifyContent:"space-between", marginBottom:20, gap:10 }}>
    <div>
      <h1 style={{ margin:0, fontFamily:font.body, fontSize:24, fontWeight:700, color:C.text }}>{title}</h1>
      {subtitle && <div style={{ fontFamily:font.body, fontSize:13, color:C.textMuted, marginTop:4 }}>{subtitle}</div>}
    </div>
    {middle}
    {action}
  </div>
);

// Quién marcó entrada hoy (en CUALQUIER tienda) y todavía no ha marcado salida — es SIEMPRE sobre
// HOY (estado en vivo de quién está trabajando ahora mismo) y de TODAS las tiendas a la vez, sin
// importar cuál tienda esté elegida en el formulario de Registrar venta ni qué cuenta/usuario esté
// viendo la pantalla — pedido explícito de Santiago: esto no depende de la cuenta ni de la tienda
// seleccionada. "En almuerzo" = su último evento de hoy fue inicio_almuerzo (ya se fue a almorzar
// y todavía no ha marcado el regreso). Se ignoran los eventos "omitido" (no son una marcación real,
// solo dejan constancia de que se saltó un paso).
const advisorsEnTurnoHoy = (records) => {
  const porUsuario = {};
  (records || []).forEach(r => {
    if (r.date !== todayStr || r.event === "omitido") return;
    const idx = ORDEN.indexOf(r.event);
    if (idx < 0) return;
    const prev = porUsuario[r.user_id];
    if (!prev || idx > prev.idx) porUsuario[r.user_id] = { userId: r.user_id, userName: r.user_name, store: r.store, idx };
  });
  return Object.values(porUsuario)
    .filter(x => x.idx < ORDEN.indexOf("salida")) // ya marcó salida ⇒ no sigue en turno, no se muestra
    .map(x => ({ ...x, enAlmuerzo: x.idx === ORDEN.indexOf("inicio_almuerzo") }))
    .sort((a, b) => a.userName.localeCompare(b.userName, "es"));
};

// Burbuja compacta (clic para desplegar nombres) que muestra quién está activo en turno / en
// almuerzo ahora mismo, en TODAS las tiendas. Pensada para vivir en el header de Registrar venta,
// en el hueco entre el título y la campana/burbuja de meta.
const EnTurnoIndicator = ({ records, stores, isMobile }) => {
  const activos = advisorsEnTurnoHoy(records);
  const enAlmuerzo = activos.filter(a => a.enAlmuerzo).length;
  const presentes = activos.length - enAlmuerzo;
  // Agrupados por tienda para que el desplegable diga dónde está cada quien, no solo el nombre.
  const porTienda = {};
  activos.forEach(a => { (porTienda[a.store] = porTienda[a.store] || []).push(a); });
  return (
    <HoverTooltip
      clickOnly
      align="right"
      width={250}
      labelStyle={{ textDecoration:"none" }}
      label={
        // Propuesta A: dos píldoras (en turno / en almuerzo) en la barra de pestañas de Ventas.
        <div style={{ display:"flex", alignItems:"center", gap:6, fontFamily:font.body, fontSize:isMobile?11.5:12, fontWeight:600, whiteSpace:"nowrap", cursor:"pointer" }}>
          {activos.length === 0 ? (
            <span style={{ display:"inline-flex", alignItems:"center", gap:6, borderRadius:99, padding:"5px 11px", background:C.surfaceHover, color:C.textMuted }}><Icon n="user" s={14}/>Nadie en turno</span>
          ) : (
            <>
              <span style={{ display:"inline-flex", alignItems:"center", gap:6, borderRadius:99, padding:"5px 11px", background:C.greenDim, color:C.green }}><Icon n="user" s={14}/>{presentes} en turno</span>
              {enAlmuerzo > 0 && <span style={{ display:"inline-flex", alignItems:"center", gap:6, borderRadius:99, padding:"5px 11px", background:C.amberDim, color:C.amber }}><Icon n="lunch" s={14}/>{enAlmuerzo} en almuerzo</span>}
            </>
          )}
        </div>
      }
    >
      <div style={{ fontFamily: font.body, fontSize: 11.5, fontWeight: 700, color: C.goldLight, marginBottom: 6 }}>Quién está en turno hoy · todas las tiendas</div>
      {activos.length === 0 ? (
        <div style={{ fontFamily: font.body, fontSize: 12, color: C.textMuted }}>Nadie ha marcado entrada hoy.</div>
      ) : (
        <div style={{ display: "flex", flexDirection: "column", gap: 10 }}>
          {Object.entries(porTienda).map(([storeId, arr]) => (
            <div key={storeId}>
              <div style={{ fontFamily: font.body, fontSize: 10.5, fontWeight: 700, color: C.textMuted, textTransform: "uppercase", letterSpacing: "0.04em", marginBottom: 4 }}>
                {stores[storeId] ? <EtiquetaTienda store={stores[storeId]} sm/> : "Sin tienda"}
              </div>
              <div style={{ display: "flex", flexDirection: "column", gap: 5 }}>
                {arr.map(a => (
                  <div key={a.userId} style={{ display: "flex", justifyContent: "space-between", alignItems: "center", gap: 8, fontFamily: font.body, fontSize: 12.5 }}>
                    <span style={{ color: C.text }}>{a.userName}</span>
                    <Badge color={a.enAlmuerzo ? C.amber : C.green} sm>{a.enAlmuerzo ? "🍽️ Almuerzo" : "🟢 Activo"}</Badge>
                  </div>
                ))}
              </div>
            </div>
          ))}
        </div>
      )}
    </HoverTooltip>
  );
};

// Comentario opcional que la propia persona deja en uno de sus registros de asistencia (ej. "Llegué
// tarde por tráfico"). Un ícono chiquito, clic para abrir una nube — no crece ni deforma la
// tarjetita del evento. `editable` debe ser true SOLO en las pantallas donde la persona ve sus
// propios registros (Marcar Asistencia, Mi Historial) — en Registros (donde admin/master ven los de
// todo el mundo) siempre va en solo lectura, y ni siquiera se muestra si no hay comentario: por
// pedido explícito de Santiago, nadie más que el dueño del registro puede agregarlo o cambiarlo.
//
// No usa HoverTooltip (que alinea la nube pegada al ícono con un simple left:0/right:0) porque este
// ícono vive dentro de tarjetitas angostas en fila (Entrada/Almuerzo/Salida) — cerca del borde
// izquierdo o derecho de la pantalla la nube quedaba cortada, con parte del texto invisible fuera
// del viewport.
//
// Ojo con `position:fixed` aquí: las pestañas de la app se animan con
// `animation: ozenPaneTab .28s ... both` — el "both" deja pegado para siempre
// `transform:translateX(0)` en el contenedor del panel (aunque sea "sin mover"), y CUALQUIER
// transform en un ancestro hace que `position:fixed` deje de medirse contra la pantalla real y
// pase a medirse contra ESE contenedor — por eso una primera versión con `fixed` + coordenadas de
// pantalla quedaba pegada muy abajo. La solución: `position:absolute` colgado del propio ícono
// (que no le importa ese transform, siempre queda bien pegado a su dueño), y solo el `left` se
// calcula con matemática de pantalla (para no salirse por los bordes) y se convierte a un offset
// LOCAL relativo al ícono — restando dos getBoundingClientRect así cancela cualquier transform de
// por medio, esté donde esté.
const ComentarioRegistro = ({ registro, editable, onGuardado }) => {
  const [show, setShow] = useState(false);
  const [popLeft, setPopLeft] = useState(0);
  const iconRef = useRef(null);
  const [valor, setValor] = useState(registro?.comentario || "");
  const [guardando, setGuardando] = useState(false);
  if (!registro) return null; // nada que comentar si el evento ni siquiera está marcado
  const tieneComentario = !!(registro.comentario || "").trim();
  if (!tieneComentario && !editable) return null; // nada que ver, y esta pantalla no puede agregarlo

  const POPUP_W = 230;
  const abrir = () => {
    const r = iconRef.current?.getBoundingClientRect();
    if (r) {
      const deseadoEnPantalla = Math.min(Math.max(r.left + r.width/2 - POPUP_W/2, 8), window.innerWidth - POPUP_W - 8);
      setPopLeft(deseadoEnPantalla - r.left); // offset LOCAL respecto al ícono, no coordenada absoluta
    }
    setShow(s=>!s);
  };

  const guardar = async () => {
    setGuardando(true);
    const { data, error } = await supabase.from("registros").update({ comentario: valor.trim() || null }).eq("id", registro.id).select().single();
    setGuardando(false);
    if (data) onGuardado?.(data);
    else if (error) alert(`No se pudo guardar el comentario: ${error.message}`);
  };

  return (
    <span style={{ position:"relative", display:"inline-block" }}>
      <span
        ref={iconRef}
        onClick={abrir}
        title={tieneComentario ? "Ver comentario" : "Agregar comentario"}
        style={{
          display: "inline-flex", alignItems: "center", justifyContent: "center", width: 20, height: 20,
          borderRadius: 99, fontSize: 12, lineHeight: 1, cursor: "pointer",
          background: tieneComentario ? `${C.gold}18` : "transparent",
          border: tieneComentario ? `1px solid ${C.borderGold}` : `1px dashed ${C.border}`,
          color: tieneComentario ? C.gold : C.textMuted, opacity: tieneComentario ? 1 : 0.6,
        }}
      >💬</span>
      {show && (
        <>
          <div onClick={()=>setShow(false)} style={{ position:"fixed", inset:0, zIndex:90 }}/>
          <div style={{
            position:"absolute", top:"calc(100% + 6px)", left:popLeft, zIndex:91, width:POPUP_W, maxWidth:"90vw",
            background:C.dark, border:`1px solid ${C.border}`, borderRadius:8, padding:"10px 12px",
            boxShadow:"0 6px 24px rgba(0,0,0,0.5)", boxSizing:"border-box",
          }}>
            {editable ? (
              <div>
                <textarea
                  value={valor}
                  onChange={e => setValor(e.target.value)}
                  placeholder="Escribe un comentario (opcional)..."
                  rows={3}
                  style={{ width: "100%", boxSizing: "border-box", background: C.surfaceAlt, border: `1px solid ${C.border}`, borderRadius: 6, padding: "6px 8px", color: C.text, fontSize: 12, fontFamily: font.body, outline: "none", resize: "vertical" }}
                />
                <div style={{ display: "flex", justifyContent: "flex-end", marginTop: 6 }}>
                  <Btn onClick={guardar} sm disabled={guardando || valor.trim()===(registro.comentario||"").trim()}>{guardando ? "Guardando..." : "Guardar"}</Btn>
                </div>
              </div>
            ) : (
              <div style={{ fontFamily: font.body, fontSize: 12.5, color: C.text, whiteSpace: "pre-wrap" }}>{registro.comentario}</div>
            )}
          </div>
        </>
      )}
    </span>
  );
};

// ── Camera Modal ──────────────────────────────────────────────────────────────
function CameraModal({ eventLabel, onCapture, onCancel }) {
  const videoRef = useRef(null), canvasRef = useRef(null), streamRef = useRef(null);
  const [ready, setReady] = useState(false), [captured, setCaptured] = useState(null), [capturedAt, setCapturedAt] = useState(null), [error, setError] = useState(null), [countdown, setCountdown] = useState(null);

  const startCamera = useCallback(async () => {
    try {
      const stream = await navigator.mediaDevices.getUserMedia({ video: { width:640, height:480, facingMode:"user" } });
      streamRef.current = stream;
      if (videoRef.current) { videoRef.current.srcObject = stream; videoRef.current.onloadedmetadata = () => { videoRef.current.play(); setReady(true); }; }
    } catch { setError("No se pudo acceder a la cámara. Verifica los permisos."); }
  }, []);
  const stopCamera = useCallback(() => { streamRef.current?.getTracks().forEach(t=>t.stop()); }, []);
  useEffect(() => { startCamera(); return () => stopCamera(); }, []);

  const takePhoto = () => {
    let c = 3; setCountdown(c);
    const iv = setInterval(() => {
      c--;
      if (c > 0) setCountdown(c);
      else {
        clearInterval(iv); setCountdown(null);
        const canvas = canvasRef.current, video = videoRef.current;
        canvas.width = video.videoWidth; canvas.height = video.videoHeight;
        canvas.getContext("2d").drawImage(video, 0, 0);
        // La hora que de verdad importa (para que no se pueda hacer trampa dejando la foto tomada
        // y demorando el "Confirmar" para ganar minutos de descanso) es la de ESTE momento — no la
        // del clic en Confirmar, que puede pasar minutos después.
        setCaptured(canvas.toDataURL("image/jpeg", 0.4));
        setCapturedAt(new Date());
        stopCamera();
      }
    }, 1000);
  };

  return (
    <div style={{ position:"fixed", inset:0, background:"rgba(0,0,0,0.9)", display:"flex", alignItems:"center", justifyContent:"center", zIndex:300, padding:16 }}>
      <div style={{ background:C.surface, borderRadius:14, border:`1px solid ${C.border}`, width:"100%", maxWidth:520, overflow:"hidden" }}>
        <div style={{ padding:"14px 16px", borderBottom:`1px solid ${C.border}`, display:"flex", justifyContent:"space-between", alignItems:"center" }}>
          <div>
            <div style={{ fontFamily:font.body, fontWeight:600, fontSize:14, color:C.text }}>📸 Foto de verificación</div>
            <div style={{ fontFamily:font.body, fontSize:11, color:C.textMuted, marginTop:2 }}>Evento: <span style={{ color:C.amber, fontWeight:600 }}>{eventLabel}</span></div>
          </div>
          <Btn onClick={()=>{ stopCamera(); onCancel(); }} variant="ghost" sm>✕</Btn>
        </div>
        <div style={{ padding:16 }}>
          {error ? (
            <div style={{ background:C.redDim, border:`1px solid ${C.red}44`, borderRadius:8, padding:16, textAlign:"center" }}>
              <div style={{ fontSize:28, marginBottom:8 }}>📵</div>
              <div style={{ fontFamily:font.body, fontSize:13, color:C.red, fontWeight:600 }}>Sin acceso a la cámara</div>
              <div style={{ fontFamily:font.body, fontSize:12, color:C.textMuted, marginTop:4 }}>{error}</div>
            </div>
          ) : (
            <div style={{ position:"relative", borderRadius:10, overflow:"hidden", background:C.dark, aspectRatio:"4/3" }}>
              {!captured && <video ref={videoRef} autoPlay muted playsInline style={{ width:"100%", height:"100%", objectFit:"cover", transform:"scaleX(-1)", display:ready?"block":"none" }} />}
              {!ready && !captured && <div style={{ position:"absolute", inset:0, display:"flex", alignItems:"center", justifyContent:"center", color:C.textMuted, fontFamily:font.body, fontSize:13 }}>Iniciando cámara...</div>}
              {countdown !== null && <div style={{ position:"absolute", inset:0, display:"flex", alignItems:"center", justifyContent:"center", background:"rgba(0,0,0,0.5)" }}><div style={{ fontFamily:font.mono, fontSize:80, fontWeight:700, color:"#fff" }}>{countdown}</div></div>}
              {captured && <img src={captured} alt="Captura" style={{ width:"100%", height:"100%", objectFit:"cover", transform:"scaleX(-1)" }} />}
              <canvas ref={canvasRef} style={{ display:"none" }} />
              {!captured && ready && countdown===null && <div style={{ position:"absolute", inset:0, display:"flex", alignItems:"center", justifyContent:"center", pointerEvents:"none" }}><div style={{ width:140, height:180, border:"2px dashed rgba(255,255,255,0.4)", borderRadius:"50%" }} /></div>}
            </div>
          )}
          {!error && (
            <div style={{ marginTop:12, display:"flex", gap:8, justifyContent:"flex-end" }}>
              {!captured ? (
                <Btn onClick={takePhoto} disabled={!ready||countdown!==null} full>📷 {countdown!==null?`Fotografiando en ${countdown}...`:"Tomar foto (3s)"}</Btn>
              ) : (
                <><Btn onClick={()=>{ setCaptured(null); setCapturedAt(null); startCamera(); }} variant="ghost">↩ Repetir</Btn><Btn onClick={()=>onCapture(captured, capturedAt)} variant="success">✓ Confirmar</Btn></>
              )}
            </div>
          )}
          <div style={{ marginTop:10, fontFamily:font.body, fontSize:11, color:C.textMuted, textAlign:"center" }}>Ubica tu rostro dentro del óvalo.</div>
        </div>
      </div>
    </div>
  );
}

// ── Nav ───────────────────────────────────────────────────────────────────────
// Asistencia (22 nov 2026, navegación nueva como Ventas): Turnos · ( + ) · Registros. "marcar" no es
// una pantalla: abre Marcar asistencia como ventana en burbuja (igual que el + de Ventas). Resumen
// (antes "Panel"), Informes y Mi Historial viven dentro de Turnos, con el selector de arriba.
const ADMIN_TABS_ASISTENCIA = [{ id:"turnos",icon:"📅",label:"Turnos" },{ id:"marcar",icon:"📍",label:"Marcar asistencia" },{ id:"records",icon:"📋",label:"Registros" }];
// Vistas dentro de Turnos (Malla · Informes · Mi Historial). Lo de hoy (antes Panel/Resumen) es
// el cuadro "Asistencia de hoy" dentro de la Malla. Cada una es una pestaña
// "escondida": la barra ilumina Turnos. Cada vista sale solo si la persona tiene su permiso.
const VISTAS_TURNOS_ASISTENCIA = [["turnos","Malla","cal"],["reports","Informes","chart"],["mi_historial","Mi Historial","history"]];
// Botones redondos "+" de la barra: "mas" = Registrar venta (Ventas), "marcar" = Marcar asistencia.
const esBotonMas = (id) => id==="mas" || id==="marcar";
// Las pestañas "Asesores" y "Tiendas" ya no van sueltas — ahora viven dentro de Turnos ▸
// Administrar (ver TurnosAdminScreen), junto con los códigos de turno especiales.
// Usuarios (control total de contraseñas) ya no va en esta lista de pestañas — es solo para
// master, y se abre aparte con un ícono discreto en el pie del menú (ver Sidebar/MobileHeader).
const ADMIN_TABS_JUNTA      = [{ id:"seguimiento",icon:"✅",label:"Seguimiento semanal" },{ id:"acuerdos",icon:"🔒",label:"Acuerdos y decisiones" },{ id:"equipo",icon:"👥",label:"Perfiles y áreas" },{ id:"guion",icon:"📖",label:"Rol de Monitor" },{ id:"indicadores",icon:"📊",label:"Indicadores" }];
// Asesor: desde el 8 oct 2026 también elige módulo al entrar (Asistencia o Escuela OZEN), igual que
// los admins. "Firmar documento" ya no es pestaña ni módulo: es una herramienta del menú de la cuenta.
// Asesores (22 nov 2026): misma navegación nueva — Turnos · ( + ) · Mi Historial.
const ADVISOR_TABS          = [{ id:"schedule",icon:"📅",label:"Turnos" },{ id:"marcar",icon:"📍",label:"Marcar asistencia" },{ id:"history",icon:"📋",label:"Mi Historial" }];
// Ventas (22 nov 2026): Métricas · ( + ) · Lista de ventas. "mas" no es una pantalla: abre Registrar
// venta como ventana encima de todo. Caja vive dentro de Métricas (Resumen · Consultas · Caja).
const ADMIN_TABS_VENTAS     = [{ id:"metricas",icon:"📊",label:"Métricas" },{ id:"mas",icon:"➕",label:"Registrar venta" },{ id:"lista",icon:"📋",label:"Lista de ventas" }];
// Escuela OZEN (área "capacitacion"): "Mis cursos" para quien toma cursos (no visualizador),
// "Progreso" para admins y visualizador, y "Administrar cursos" para todos los admins.
const ADMIN_TABS_CAPACITACION = [{ id:"mis_cursos",icon:"📚",label:"Mis cursos" },{ id:"progreso",icon:"📊",label:"Progreso" },{ id:"cursos_admin",icon:"🛠️",label:"Administrar cursos" }];
// Operaciones (área "operaciones"): por ahora solo Externas (parte 1). Internas e Indicadores son
// las partes 2 y 3 — ver "OPERACIONES" más abajo.
const ADMIN_TABS_OPERACIONES = [{ id:"op_externas",icon:"🧰",label:"Externas · clientes" },{ id:"op_internas",icon:"📦",label:"Internas · tiendas" },{ id:"op_indicadores",icon:"📊",label:"Indicadores" },{ id:"op_producto",icon:"🏷️",label:"Producto" }];
const tabsCapacitacion = (user) => ADMIN_TABS_CAPACITACION.filter(t => t.id==="mis_cursos" ? tomaCapacitaciones(user) : t.id==="cursos_admin" ? puedeEditarCapacitacion(user) : puede(user, "escuela.progreso"));
const puedeUsarAreas = (user) => user.role==="admin" || user.role==="master" || user.role==="visualizador" || user.role==="admin_finanzas" || user.role==="admin_turnos";
// Quién ve la pantalla de módulos al entrar y el selector de áreas arriba: los admins (puedeUsarAreas)
// y los asesores (solo Asistencia y Escuela OZEN). La cuenta de tienda no: va directo a Ventas.
const eligeModulo = (user) => puedeUsarAreas(user) || user.role==="advisor";
// Quién puede elegir el área "Ventas" desde el selector. Admin y Visualizador entran en modo
// solo lectura (ver ventasSoloLectura); master y admin_finanzas entran completo.
const puedeUsarVentasArea = (user) => user.role==="master" || user.role==="admin_finanzas" || user.role==="admin" || user.role==="visualizador" || user.role==="admin_turnos";
// Quién solo puede VER Ventas (lista, métricas, caja) sin registrar ni corregir nada.
const ventasSoloLectura = (user) => user.role==="admin" || user.role==="visualizador" || user.role==="admin_turnos";
// Todo el que entra a Ventas ve la pestaña Registrar venta. Admin, Admin Turnos y Visualizador
// entran en modo solo lectura: pueden llenar el formulario para ver cómo funciona, pero no
// guardar (ver puedeRegistrarVenta). Antes el Visualizador ni veía la pestaña — pedido de Santiago
// (nov 2026, revisión del inventario de Permisos): que la vea igual que un Admin.
// (Aquí vivía `puedeVerRegistrar`; desde la Fase 3 de Permisos es `puede(user, "ventas.registrar.ver")`.)
const puedeRegistrarVenta = (user) => user.role==="master" || user.role==="admin_finanzas";
// Cuentas de tienda: login compartido, van directo a Ventas sin selector de área
const esCuentaTienda = (user) => user.role==="tienda";
// Turnos: además de los asesores, los admin (master/admin/admin_finanzas/visualizador) también
// pueden aparecer como columna en la malla y que se les asigne un turno propio para marcar
// asistencia — no se fusiona su cuenta con ninguna de asesor, solo se les habilita la malla.
const esAdminAsignableATurnos = (u) => ["master","admin","admin_finanzas","admin_turnos","visualizador"].includes(u.role);
// Quién puede EDITAR el Borrador o entrar a Administrar (asesores/tiendas/horarios) en Turnos —
// master y admin_turnos (un admin normal con acceso completo a Turnos, y solo a eso). admin_finanzas
// es un admin normal con acceso extra a VENTAS, no a Turnos, así que ahí se comporta igual que
// "admin"/"visualizador": solo puede ver la rejilla.
// (Aquí vivía `puedeGestionarTurnos`; desde la Fase 3 de Permisos es `permisosTurnos(user)`, acción por acción.)
const ROLE_ORDEN_TURNOS = ["master","admin","admin_finanzas","admin_turnos","visualizador"];
const esUsuarioDeTurnos = (u) => u.role==="advisor" || esAdminAsignableATurnos(u);
// Los asesores usan el campo general `active` (ya existente). Los admin usan un campo propio
// `activo_en_turnos` para no interferir con el `active` general que ya se usa en otras pantallas
// (ej. Caja, para elegir quién recibe una recolección). Si la columna aún no existe o es null,
// se trata como activo por defecto.
const activoEnMallaTurnos = (u) => u.role==="advisor" ? !!u.active : (u.active!==false && u.activo_en_turnos!==false);
// Orden manual de columnas en la rejilla (ver botones ◀▶ en el Borrador) — campo `orden_turnos`
// en usuarios, null si nunca se ha movido a nadie (esos quedan al final, ordenados por nombre).
const advisorsOrdenTurnos = (users) => users
  .filter(u=>esUsuarioDeTurnos(u) && activoEnMallaTurnos(u))
  .sort((a,b)=> (a.orden_turnos??9999)-(b.orden_turnos??9999) || a.name.localeCompare(b.name));
// Columnas de la malla de UN mes (pedido de Santiago):
//  · Meses pasados: SOLO quienes tuvieron al menos un turno ese mes (activos o ya retirados) — así
//    no aparecen asesores que ingresaron después.
//  · Rejilla "Turnos" (consulta), cualquier mes: solo quienes tienen al menos un turno ese mes —
//    nada de columnas vacías (asesores o admin sin turnos).
//  · Borrador, mes actual y futuros (`todosLosActivos`): todos los activos, porque ahí se asignan.
// Los que ya no están activos van al final, por nombre, marcados con `_retirado` (encabezado gris,
// sin flechas para mover).
const columnasMallaMes = (users, activos, asignacionesMes, { mesPasado=false, todosLosActivos=false } = {}) => {
  const conTurno = new Set(asignacionesMes.map(a=>a.asesor_id));
  const visibles = activos.filter(a => conTurno.has(a.id) || (!mesPasado && todosLosActivos));
  const idsActivos = new Set(activos.map(a=>a.id));
  const retirados = users
    .filter(u=>!idsActivos.has(u.id) && conTurno.has(u.id))
    .sort((a,b)=>(a.name||"").localeCompare(b.name||""))
    .map(u=>({ ...u, _retirado:true }));
  return [...visibles, ...retirados];
};
// ¿El mes (anio, mes 0-11) ya pasó? (anterior al mes en curso, hora Colombia)
const esMesPasadoTurnos = (anio, mes) => { const h = toColombiaDate(); return anio < h.getFullYear() || (anio===h.getFullYear() && mes < h.getMonth()); };
// Admin Finanzas: hace todo lo de un Administrador normal (Asistencia/Junta), más Ventas completo
// (registrar, lista, métricas, asignar metas, aprobar notas crédito y corregir por error).
// (Aquí vivía `esAdminFinanzas`; el menú "Acceso tiendas" ahora sale de `cuenta.acceso_tiendas`.)
// Cualquier admin (master, admin, admin finanzas, admin turnos) puede vender cuando está en una
// tienda, aunque su cuenta no tenga permiso para REGISTRAR la venta desde Ventas (ej. un Admin
// normal, que ahí solo puede ver) — por eso también aparecen como opción de "quién hizo la venta"
// / asesor en Registrar venta, Lista de ventas, Métricas y Caja, sin importar su rol en Ventas.
const ROLES_ADMIN_VENDEDOR = ["master","admin","admin_finanzas","admin_turnos"];
const esVendedorPosible = (u) => puede(u, "ventas.vendedor") && u.active;   // Permisos, Fase 3
// Quién puede aprobar/rechazar notas crédito dentro de Ventas
const esAdminDeVentas = (user) => user.role==="master" || user.role==="admin_finanzas";
// Quién puede asignar las metas mensuales en Métricas
// (Aquí vivía `puedeAsignarMetas`; desde la Fase 3 de Permisos es `puede(user, "ventas.metas.asignar")`.)
// Quién puede registrar una recolección de efectivo: master/admin finanzas, y la cuenta de la
// tienda (porque son quienes ven la caja físicamente y confirman si estaba completa o no).
// Ojo: NO incluye a los usuarios individuales de "advisor" (esos son solo para Asistencia).
// (Antes aquí vivía `puedeHacerRecoleccion`. Desde la Fase 3 de Permisos esa pregunta es
// `puede(user, "caja.recoleccion.registrar")` — con los mismos tres roles sembrados en la base.)
// Qué pestañas le corresponden a cada quien, según su rol y el área elegida. La cuenta de tienda
// no elige área (va directo a Ventas), así que Operaciones le llega como una pestaña más.
// Pestañas de Ventas que le tocan a cada quien. Caja ya se decide con puede() (Permisos, Fase 3).
const PERMISO_DE_TAB_VENTAS = { registrar:"ventas.registrar.ver", mas:"ventas.registrar.ver", lista:"ventas.lista.ver", metricas:"ventas.metricas.ver", caja:"caja.ver" };
// Quien ve Caja pero no Métricas conserva Caja como pestaña propia.
const tabsVentas = (user) => { const t = ADMIN_TABS_VENTAS.filter(x => puede(user, PERMISO_DE_TAB_VENTAS[x.id])); if(!puede(user, "ventas.metricas.ver") && puede(user, "caja.ver")) t.push({ id:"caja", icon:"💰", label:"Caja" }); return t; };
// Asistencia y Turnos (Permisos, Fase 3): cada pestaña sale si la persona tiene su permiso.
const PERMISO_DE_TAB_ASISTENCIA = { dashboard:"asistencia.panel", records:"asistencia.registros.ver", turnos:"turnos.ver", marcar:"asistencia.marcar", mi_historial:"asistencia.historial", reports:"asistencia.informes", checkin:"asistencia.marcar", history:"asistencia.historial", schedule:"turnos.ver" };
// Las vistas de Turnos que le tocan a cada quien. La pestaña Turnos sale si tiene al menos una.
const vistasTurnosAsistencia = (user) => VISTAS_TURNOS_ASISTENCIA.filter(([id]) => puede(user, PERMISO_DE_TAB_ASISTENCIA[id]));
const tabsAsistencia = (user) => centrarMas(ADMIN_TABS_ASISTENCIA.filter(t => t.id==="turnos" ? vistasTurnosAsistencia(user).length>0 : puede(user, PERMISO_DE_TAB_ASISTENCIA[t.id])));
const tabsAsesor = (user) => centrarMas(ADVISOR_TABS.filter(t => puede(user, PERMISO_DE_TAB_ASISTENCIA[t.id])));
// Pantalla con la que abre Asistencia: Turnos (o la primera vista que pueda ver); el + nunca.
const inicioAsistencia = (user) => {
  if(user.role==="advisor") return tabsAsesor(user).find(t=>!esBotonMas(t.id))?.id || "schedule";
  return vistasTurnosAsistencia(user)[0]?.[0] || (puede(user, "asistencia.registros.ver") ? "records" : "turnos");
};
// Qué puede hacer en Turnos, acción por acción. `algo` = tiene al menos una (para mostrar Editar/⚙).
const permisosTurnos = (user) => {
  const t = { editar:puede(user, "turnos.editar"), publicar:puede(user, "turnos.publicar"), asesores:puede(user, "turnos.asesores"), tiendas:puede(user, "turnos.tiendas"), especiales:puede(user, "turnos.especiales"), horarios:puede(user, "turnos.horarios"), mallaActivos:puede(user, "turnos.malla_activos") };
  return { ...t, administrar: t.asesores || t.tiendas || t.especiales || t.horarios, algo: Object.values(t).some(Boolean) };
};
// El + (Registrar venta) siempre en el centro: sus vecinos son las pestañas de Ventas y lo demás
// (Turnos, Operaciones…) se reparte por fuera, una a cada lado (22 nov 2026).
const centrarMas = (tabs) => {
  const i = tabs.findIndex(t=>esBotonMas(t.id)); if(i<0) return tabs;
  const izq = tabs.slice(0, i), der = tabs.slice(i+1);
  const extras = [...izq.slice(0, Math.max(0, izq.length-1)), ...der.slice(1)];
  const L = izq.slice(-1), R = der.slice(0,1);
  extras.forEach((t,k)=>{ if(k%2===0) L.unshift(t); else R.push(t); });
  return [...L, tabs[i], ...R];
};
const tabsPara = (user, area, liderOper="") => !puedeUsarAreas(user)
  ? (esCuentaTienda(user) ? centrarMas([...tabsVentas(user), ...(puede(user, "turnos.ver") ? [{ id:"turnos", icon:"📅", label:"Turnos" }] : []), ...(puedeOper(user, "operaciones.ver") ? [{ id:"op_externas", icon:"🧰", label:"Operaciones" }] : [])]) : area==="capacitacion" ? tabsCapacitacion(user) : tabsAsesor(user))
  : (area==="junta" ? ADMIN_TABS_JUNTA.filter(()=>puede(user, "junta.ver")) : area==="operaciones" ? ADMIN_TABS_OPERACIONES.filter(t=>(t.id!=="op_indicadores" || puedeOper(user, "operaciones.indicadores.ver")) && (t.id!=="op_producto" || puedeOper(user, "operaciones.producto.ver", liderOper))) : area==="ventas" ? tabsVentas(user) : area==="capacitacion" ? tabsCapacitacion(user) : tabsAsistencia(user));

// ── Vencimiento de contraseña ────────────────────────────────────────────────
const DIAS_EXPIRACION_PASSWORD = 90;
const passwordVencida = (u) => {
  if (!u.password_updated_at) return true;
  const dias = (Date.now() - new Date(u.password_updated_at).getTime()) / 86400000;
  return dias >= DIAS_EXPIRACION_PASSWORD;
};

// ── Navegación (Propuesta A · "Mostrador") ───────────────────────────────────
// Sin barra lateral: arriba una barra con la marca, las ÁREAS como selector (se cambia de área con
// un clic, sin volver a la pantalla de módulos), la TIENDA activa y el menú de la cuenta. Debajo,
// las pestañas del área con una línea que se desliza a la pestaña elegida, y bajo ellas una franja
// fina del color de la tienda (cuando la pantalla trabaja sobre una tienda). En celular las
// pestañas bajan a una barra inferior, como antes.
const TAB_ICON = { marcar:"pin", mi_historial:"history", dashboard:"grid", records:"list", turnos:"cal", mi_asistencia:"pin", reports:"chart", seguimiento:"check", acuerdos:"lock", equipo:"users", guion:"flag", indicadores:"chart", checkin:"pin", history:"history", schedule:"cal", firmar:"pen", registrar:"plus", lista:"list", metricas:"chart", caja:"wallet", mis_cursos:"book", progreso:"chart", cursos_admin:"wrench", op_externas:"wrench", op_internas:"box", op_indicadores:"chart", op_producto:"tag" };
const AREAS_NAV = [
  { id:"ventas", label:"Ventas", ic:"receipt" },
  { id:"operaciones", label:"Operaciones", ic:"box" },
  { id:"asistencia", label:"Asistencia", ic:"clock" },
  { id:"junta", label:"La Junta", ic:"users" },
  // Escuela OZEN: internamente el área se sigue llamando "capacitacion". En celular el selector de
  // áreas es una fila de botones: ahí se muestra el nombre corto.
  { id:"capacitacion", label:"Escuela OZEN", corto:"Escuela", ic:"book" },
];
const areasPara = (user) => AREAS_NAV.filter(a => user.role==="advisor" ? (a.id==="asistencia" || a.id==="capacitacion") : ((a.id!=="ventas" || puedeUsarVentasArea(user)) && (a.id!=="operaciones" || puedeOper(user, "operaciones.ver"))));
// "OZEN Unicentro" → "Unicentro": en la barra y en las etiquetas el prefijo de marca sobra.
const nombreTiendaCorto = (s) => (s?.name || "").replace(/^OZEN\s+/i, "") || "—";
const colorTienda = (s) => s?.color || "#6b7280";

// Punto de color de una tienda (con un halo suave del mismo color).
const PuntoTienda = ({ color, size=9 }) => (
  <span style={{ width:size, height:size, borderRadius:"50%", background:color, boxShadow:`0 0 0 3px ${hexToRgba(color,0.18)}`, display:"inline-block", flexShrink:0 }}/>
);
// Etiqueta de tienda para listas e historiales donde se mezclan tiendas: punto + nombre sobre un
// fondo muy suave del color de la tienda (10 %) — identifica sin gritar.
const EtiquetaTienda = ({ store, sm }) => {
  const col = colorTienda(store);
  return (
    <span style={{ display:"inline-flex", alignItems:"center", gap:6, fontFamily:font.body, fontSize:sm?11:12, fontWeight:600, color:C.text, borderRadius:99, padding:sm?"2px 9px 2px 7px":"3px 11px 3px 9px", background:hexToRgba(col,0.1), whiteSpace:"nowrap" }}>
      <span style={{ width:sm?6:7, height:sm?6:7, borderRadius:"50%", background:col, flexShrink:0 }}/>{nombreTiendaCorto(store)}
    </span>
  );
};

// Menú flotante (tienda, cuenta). Un clic fuera lo cierra.
function MenuFlotante({ abierto, onCerrar, children, align="right", width=250, top=46 }) {
  if(!abierto) return null;
  return (
    <>
      <div onClick={onCerrar} style={{ position:"fixed", inset:0, zIndex:90 }}/>
      <div className="ozen-menu-pop" style={{ position:"absolute", top, [align]:0, width, background:"#fff", border:`1px solid ${C.border}`, borderRadius:12, boxShadow:"0 20px 40px -18px rgba(26,59,82,0.45)", padding:6, zIndex:91 }}>{children}</div>
    </>
  );
}
const MenuItem = ({ ic, children, onClick, color, activo, extra }) => (
  <button onClick={onClick} className="ozen-menu-item" style={{ display:"flex", alignItems:"center", gap:10, width:"100%", padding:"10px 12px", border:"none", background:activo?C.surfaceHover:"none", borderRadius:8, cursor:"pointer", fontFamily:font.body, fontSize:13.5, fontWeight:activo?600:400, color:color||C.text, textAlign:"left" }}>
    {ic}{children}{extra && <span style={{ marginLeft:"auto" }}>{extra}</span>}
  </button>
);

// Registrar venta / Caja sin tienda elegida (ya no se elige ninguna por defecto — pedido de
// Santiago): la pantalla queda sin datos y solo indica que se elige arriba, en el selector.
const SinTiendaElegida = () => (
  <div style={{ display:"flex", alignItems:"center", justifyContent:"flex-end", gap:8, fontFamily:font.body, fontSize:13, color:C.textMuted, padding:"6px 4px" }}>
    Elige una tienda arriba para ver sus datos <Icon n="up" s={14} sw={2.2} style={{ color:C.gold }}/>
  </div>
);

function SelectorTienda({ stores, tiendaId, setTiendaId, fija, compact }) {
  const [abierto, setAbierto] = useState(false);
  const actual = stores[tiendaId];
  const chip = { display:"flex", alignItems:"center", gap:8, border:`1px solid ${C.border}`, borderRadius:10, padding:compact?"6px 10px":"7px 12px", background:"#fff", fontFamily:font.body, fontSize:compact?12.5:13, fontWeight:600, color:C.text, whiteSpace:"nowrap" };
  if(fija || !setTiendaId) return <div style={chip}><PuntoTienda color={colorTienda(actual)} size={compact?8:9}/>{nombreTiendaCorto(actual)}</div>;
  return (
    <div style={{ position:"relative" }}>
      <button onClick={()=>setAbierto(a=>!a)} style={{ ...chip, cursor:"pointer", ...(actual ? {} : { border:`1.5px dashed ${C.gold}`, color:C.gold }) }} title="Tienda con la que estás trabajando">
        {actual ? <><PuntoTienda color={colorTienda(actual)} size={compact?8:9}/>{nombreTiendaCorto(actual)}</> : <><Icon n="store" s={14}/>Elige tienda</>}<Icon n="down" s={14} style={{ color:C.textMuted }}/>
      </button>
      <MenuFlotante abierto={abierto} onCerrar={()=>setAbierto(false)} width={230}>
        <div style={{ fontFamily:font.body, fontSize:10.5, letterSpacing:"0.1em", textTransform:"uppercase", color:C.textMuted, padding:"6px 12px 4px", fontWeight:600 }}>Tienda</div>
        {tiendasVenta(stores).map(t=>(
          <MenuItem key={t.id} activo={t.id===tiendaId} onClick={()=>{ setTiendaId(t.id); setAbierto(false); }} ic={<PuntoTienda color={colorTienda(t)}/>} extra={t.id===tiendaId ? <Icon n="check" s={15} style={{ color:C.gold }}/> : null}>{nombreTiendaCorto(t)}</MenuItem>
        ))}
      </MenuFlotante>
    </div>
  );
}

// Menús que se deslizan de lado en el celular: al entrar, se mueven solos hacia la derecha y
// vuelven, para que se note que hay más opciones escondidas (pedido de Santiago). Se repite un
// par de veces mientras nadie lo toque; en cuanto la persona lo toca, deja de moverse. Si todo
// cabe en la pantalla, no hace nada.
function useAvisoDeslizar(ref, activo=true){
  useEffect(()=>{
    const el = ref.current;
    if(!activo || !el) return;
    let tocado = false, veces = 0, timers = [];
    const parar = () => { tocado = true; timers.forEach(clearTimeout); };
    el.addEventListener("touchstart", parar, { passive:true });
    el.addEventListener("pointerdown", parar);
    const reduce = window.matchMedia && window.matchMedia("(prefers-reduced-motion: reduce)").matches;
    const mover = () => {
      if(tocado || veces>=3) return;
      const extra = el.scrollWidth - el.clientWidth;
      if(extra < 8) return;
      veces++;
      const inicio = el.scrollLeft;
      el.scrollTo({ left: inicio + Math.min(extra, 140), behavior: reduce ? "auto" : "smooth" });
      timers.push(setTimeout(()=>{ if(!tocado) el.scrollTo({ left: inicio, behavior: reduce ? "auto" : "smooth" }); }, 900));
      timers.push(setTimeout(mover, 9000));
    };
    timers.push(setTimeout(mover, 1200));
    return () => { parar(); el.removeEventListener("touchstart", parar); el.removeEventListener("pointerdown", parar); };
  }, [ref, activo]);
}

function SelectorArea({ user, area, onChooseArea, compact }) {
  // En celular cada botón mide lo que mide su texto (no repartidos en partes iguales) y la fila se
  // desliza de lado, con el aviso de movimiento de arriba. El botón activo queda siempre a la vista.
  const fila = useRef(null);
  useAvisoDeslizar(fila, !!compact);
  useEffect(()=>{ if(!compact || !fila.current) return; const on = fila.current.querySelector("[data-activo='1']"); on && on.scrollIntoView({ inline:"nearest", block:"nearest" }); }, [area, compact]);
  return (
    <div ref={fila} className={compact?"ozen-sin-barra":undefined} style={{ display:"flex", background:C.surfaceHover, borderRadius:99, padding:4, gap:2, ...(compact?{ width:"100%", overflowX:"auto", scrollbarWidth:"none", WebkitOverflowScrolling:"touch", boxSizing:"border-box" }:{}) }}>
      {areasPara(user).map(a=>{ const on=a.id===area; return (
        <button key={a.id} data-activo={on?"1":"0"} onClick={()=>!on && onChooseArea(a.id)} className="ozen-area-btn" style={{ flex:compact?"0 0 auto":undefined, whiteSpace:"nowrap", display:"flex", alignItems:"center", justifyContent:"center", gap:7, padding:compact?"7px 14px":"8px 16px", borderRadius:99, border:"none", cursor:on?"default":"pointer", background:on?C.goldDark:"transparent", color:on?"#fff":C.textSub, fontFamily:font.body, fontSize:compact?11.5:13, fontWeight:on?600:500, transition:"background .25s ease, color .25s ease", whiteSpace:"nowrap" }}>
          {!compact && <Icon n={a.ic} s={15}/>}{compact ? (a.corto||a.label) : a.label}
        </button>
      ); })}
    </div>
  );
}

function MenuCuenta({ user, onLogout, onCambiarPassword, onAbrirAccesoTiendas, onActivarNotificaciones, onAbrirFirmas }) {
  const [abierto, setAbierto] = useState(false);
  const [sonNavidad, setSonNavidad] = useState(() => sonidosNavidadActivos()); // Navidad: cada quien puede apagar los sonidos de temporada
  const cerrarY = (fn) => () => { setAbierto(false); fn(); };
  const nombre = esCuentaTienda(user) ? user.name : user.name.split(" ")[0];
  return (
    <div style={{ position:"relative" }}>
      <button onClick={()=>setAbierto(a=>!a)} title="Tu cuenta" style={{ width:36, height:36, borderRadius:"50%", background:C.tinta, border:"none", display:"grid", placeItems:"center", fontFamily:font.body, fontSize:14, fontWeight:700, color:C.goldDark, cursor:"pointer" }}>{(esCuentaTienda(user) ? (user.name||"").replace(/^\s*ozen\s+/i,"") : (user.name||""))[0]?.toUpperCase() || "?"}</button>
      <MenuFlotante abierto={abierto} onCerrar={()=>setAbierto(false)} width={250}>
        <div style={{ padding:"10px 12px 12px", borderBottom:`1px solid ${C.border}`, marginBottom:4 }}>
          <div style={{ fontFamily:font.body, fontSize:14, fontWeight:700, color:C.text, textTransform:esCuentaTienda(user)?"uppercase":"none" }}>{nombre}</div>
          <div style={{ fontFamily:font.body, fontSize:11, color:C.textMuted, textTransform:"uppercase", letterSpacing:"0.06em", marginTop:2 }}>{ROLE_LABEL[user.role] || "Asesor"}</div>
        </div>
        {puede(user, "cuenta.firmar") && <MenuItem ic={<Icon n="pen" s={16}/>} onClick={cerrarY(onAbrirFirmas)}>Firmar documento</MenuItem>}
        {permCondicion(user, "cuenta.acceso_tiendas")===null && <MenuItem ic={<Icon n="store" s={16}/>} onClick={cerrarY(onAbrirAccesoTiendas)}>Acceso tiendas</MenuItem>}
        {puede(user, "asistencia.avisos") && notificacionesSoportadas() && (!pushActivo()||requiereInstalarEnIOS()) && <MenuItem ic={<Icon n="bell" s={16}/>} onClick={cerrarY(onActivarNotificaciones)}>Activar notificaciones</MenuItem>}
        {permCondicion(user, "cuenta.password")===null && <MenuItem ic={<Icon n="key" s={16}/>} onClick={cerrarY(onCambiarPassword)}>Mi contraseña</MenuItem>}
        {NAVIDAD && <MenuItem ic={<Icon n="bell" s={16}/>} onClick={()=>{ const v=!sonNavidad; setSonNavidad(v); guardarSonidosNavidad(v); if(v) sonidoNavidadIngreso(); }} extra={<span style={{ fontSize:12, fontWeight:700, color:sonNavidad?C.green:C.textMuted }}>{sonNavidad?"Sí":"No"}</span>}>Sonidos de Navidad</MenuItem>}
        <MenuItem ic={<Icon n="logout" s={16}/>} color={C.red} onClick={cerrarY(onLogout)}>Cerrar sesión</MenuItem>
      </MenuFlotante>
    </div>
  );
}

// Marca: el logo, para master, también es la entrada a Usuarios — a propósito sin ningún aviso
// visual, y hay que mantenerlo presionado (no un clic normal) para entrar.
function MarcaOzen({ user, onAbrirUsuarios, compact }) {
  const puedeUsuarios = puede(user, "cuenta.usuarios");   // Permisos, Fase 3 (master nunca lo pierde)
  const presionarLogo = useLongPress(onAbrirUsuarios);
  // Logo real de la marca (solo "OZEN", sin "momento presente") — recortado del logo oficial.
  const logo = (
    <img src="/logo-wordmark.png" alt="OZEN" draggable={false} onContextMenu={e=>puedeUsuarios&&e.preventDefault()} {...(puedeUsuarios?presionarLogo:{})} style={{ height:compact?22:26, width:"auto", display:"block", flexShrink:0, cursor:puedeUsuarios?"pointer":"default", userSelect:"none", WebkitTouchCallout:"none" }} />
  );
  // Navidad (1 nov – 6 ene): la estrella del logo brilla, en todas las pantallas. Ver src/navidad.jsx.
  if(NAVIDAD) return (
    <span style={{ position:"relative", display:"inline-block", flexShrink:0 }}>
      <EstilosNavidad/>{logo}<BrilloEstrellaLogo x="5.4%" y="21%" tam={compact?24:30}/>
    </span>
  );
  if(!HALLOWEEN) return logo;
  // Octubre: dos murciélagos chiquitos revoloteando junto al logo — siempre visibles en todas las
  // pantallas, para que se sienta Halloween sin estorbar. Se van solos el 1 de noviembre.
  return (
    <span style={{ position:"relative", display:"inline-block", flexShrink:0 }}>
      {logo}
      <span aria-hidden="true" className="ozen-bat-flota" style={{ position:"absolute", top:compact?-7:-8, right:compact?-24:-28, pointerEvents:"none" }}><Murcielago w={compact?19:22} color={C.goldDark}/></span>
      <span aria-hidden="true" className="ozen-bat-flota ozen-bat-flota-2" style={{ position:"absolute", top:compact?6:8, right:compact?-38:-44, pointerEvents:"none", opacity:0.55 }}><Murcielago w={compact?11:13} color={C.goldDark}/></span>
    </span>
  );
}

const BotonRefrescar = ({ onRefresh, refreshing }) => (
  <button onClick={onRefresh} disabled={refreshing} title="Actualizar datos" style={{ width:36, height:36, borderRadius:10, border:"none", background:"transparent", display:"grid", placeItems:"center", color:C.textSub, cursor:refreshing?"not-allowed":"pointer", opacity:refreshing?0.5:1 }}>
    <Icon n="refresh" s={18} style={{ transition:"transform .6s ease", transform:refreshing?"rotate(360deg)":"none" }}/>
  </button>
);

function BarraSuperior({ extraDerecha, campana, user, area, onChooseArea, stores, tiendaId, setTiendaId, tiendaFija, mostrarTienda, onLogout, onRefresh, refreshing, onCambiarPassword, onAbrirUsuarios, onAbrirAccesoTiendas, onActivarNotificaciones, onAbrirFirmas }) {
  return (
    <div style={{ height:62, background:"#fff", borderBottom:`1px solid ${C.border}`, display:"grid", gridTemplateColumns:"1fr auto 1fr", alignItems:"center", padding:"0 24px", gap:20, flexShrink:0, position:"relative", zIndex:20 }}>
      {/* 22 nov 2026: los módulos van centrados (marca a la izquierda, cuenta a la derecha). */}
      <div style={{ display:"flex", alignItems:"center", minWidth:0 }}><MarcaOzen user={user} onAbrirUsuarios={onAbrirUsuarios}/></div>
      <div style={{ display:"flex", justifyContent:"center" }}>{eligeModulo(user) && <SelectorArea user={user} area={area} onChooseArea={onChooseArea}/>}</div>
      <div style={{ display:"flex", alignItems:"center", justifyContent:"flex-end", gap:14, minWidth:0 }}>
        {extraDerecha}
        {mostrarTienda && <SelectorTienda stores={stores} tiendaId={tiendaId} setTiendaId={setTiendaId} fija={!!tiendaFija}/>}
        <BotonRefrescar onRefresh={onRefresh} refreshing={refreshing}/>
        {campana}
        <MenuCuenta user={user} onLogout={onLogout} onCambiarPassword={onCambiarPassword} onAbrirAccesoTiendas={onAbrirAccesoTiendas} onActivarNotificaciones={onActivarNotificaciones} onAbrirFirmas={onAbrirFirmas}/>
      </div>
      {NAVIDAD && <GuirnaldaBarra/>}
    </div>
  );
}

// Pestañas del área, con la línea inferior que se DESLIZA hasta la pestaña elegida (en vez de
// saltar). Se mide la posición real de la pestaña activa y la línea se anima a ese sitio.
function BarraPestanas({ tabs, tab, setTab, derecha }) {
  const refs = useRef({});
  const [linea, setLinea] = useState(null);
  useLayoutEffect(()=>{
    const medir = () => { const el = refs.current[tab]; if(el) setLinea({ left:el.offsetLeft, width:el.offsetWidth }); };
    medir();
    window.addEventListener("resize", medir);
    return () => window.removeEventListener("resize", medir);
  }, [tab, tabs.length]);
  return (
    <div style={{ height:50, background:"#fff", borderBottom:`1px solid ${C.border}`, display:"grid", gridTemplateColumns:"1fr auto 1fr", alignItems:"stretch", padding:"0 24px", gap:20, flexShrink:0 }}>
      <div/>
      <div style={{ display:"flex", alignItems:"stretch", gap:30, position:"relative" }}>
      {tabs.map(t=>{ const on=t.id===tab; if(esBotonMas(t.id)) return (
        <button key={t.id} onClick={(e)=>setTab(t.id, e.currentTarget.getBoundingClientRect())} title={t.label} aria-label={t.label} className="ozen-boton-mas" style={{ alignSelf:"center", width:40, height:40, borderRadius:"50%", border:"none", background:C.gold, color:"#fff", display:"grid", placeItems:"center", cursor:"pointer", boxShadow:"0 6px 16px -6px rgba(26,59,82,0.55)", flexShrink:0 }}><Icon n="plus" s={20} sw={2.6}/></button>
      ); return (
        <button key={t.id} ref={el=>{ refs.current[t.id]=el; }} onClick={()=>setTab(t.id)} className="ozen-tab-btn" style={{ display:"flex", alignItems:"center", gap:8, border:"none", background:"none", padding:0, cursor:"pointer", fontFamily:font.body, fontSize:14, fontWeight:on?600:400, color:on?C.goldDark:C.textMuted, transition:"color .2s ease", whiteSpace:"nowrap" }}>
          <Icon n={TAB_ICON[t.id]||"right"} s={16}/>{t.label}
        </button>
      ); })}
      {linea && <span className="ozen-tab-linea" style={{ position:"absolute", bottom:0, height:2.5, borderRadius:2, background:C.gold, left:linea.left, width:linea.width }}/>}
      </div>
      <div style={{ display:"flex", alignItems:"center", justifyContent:"flex-end", gap:10 }}>{derecha}</div>
    </div>
  );
}

// Franja de 3 px con el color de la tienda activa — dice "dónde estás" en toda el área de Ventas.
const FranjaTienda = ({ color }) => <div style={{ height:3, background:color, transition:"background-color .35s ease", flexShrink:0 }}/>;

function BarraSuperiorMovil({ extra, campana, user, area, onChooseArea, stores, tiendaId, setTiendaId, tiendaFija, mostrarTienda, onLogout, onRefresh, refreshing, onCambiarPassword, onAbrirUsuarios, onAbrirAccesoTiendas, onActivarNotificaciones, onAbrirFirmas }) {
  return (
    <div style={{ background:"#fff", borderBottom:`1px solid ${C.border}`, padding:"10px 14px", paddingTop:"calc(10px + env(safe-area-inset-top, 0px) * 1.55)", flexShrink:0, position:"relative", zIndex:20 }}>
      <div style={{ display:"flex", alignItems:"center", gap:8 }}>
        <MarcaOzen user={user} onAbrirUsuarios={onAbrirUsuarios} compact/>
        <div style={{ flex:1 }}/>
        {mostrarTienda && <SelectorTienda stores={stores} tiendaId={tiendaId} setTiendaId={setTiendaId} fija={!!tiendaFija} compact/>}
        <BotonRefrescar onRefresh={onRefresh} refreshing={refreshing}/>
        {campana}
        <MenuCuenta user={user} onLogout={onLogout} onCambiarPassword={onCambiarPassword} onAbrirAccesoTiendas={onAbrirAccesoTiendas} onActivarNotificaciones={onActivarNotificaciones} onAbrirFirmas={onAbrirFirmas}/>
      </div>
      {eligeModulo(user) && <div style={{ marginTop:10 }}><SelectorArea user={user} area={area} onChooseArea={onChooseArea} compact/></div>}
      {extra && <div style={{ marginTop:8, display:"flex", justifyContent:"flex-end" }}>{extra}</div>}
      {NAVIDAD && <GuirnaldaBarra isMobile/>}
    </div>
  );
}

// Ventana en "nube" que sale de un botón + (22 nov 2026), con vidrio esmerilado ("liquid glass"):
// en computador baja desde el + con una colita que lo señala; en celular (o si el + está abajo)
// sube desde el +. La usan Registrar venta (Ventas) y Marcar asistencia (Asistencia).
// `origen` = dónde está el + en pantalla (getBoundingClientRect); `centro` = lo que va en el medio
// de la franja de arriba (ej. selector de tienda). Mostrar/esconder con `abierta` (escondida queda
// montada, así lo escrito no se pierde — Registrar venta lo usa así).
function VentanaNube({ abierta, origen, isMobile, onCerrar, icono="plus", titulo, centro, tituloCerrar="Cerrar", children }) {
  const vw = typeof window!=="undefined" ? window.innerWidth : 1200, vh = typeof window!=="undefined" ? window.innerHeight : 800;
  const anchoVent = isMobile ? vw-16 : Math.min(1180, vw-32);
  const origenX = origen ? origen.left + origen.width/2 : vw/2;
  const izqVent = isMobile ? 8 : Math.max(16, Math.min(vw-anchoVent-16, origenX-anchoVent/2));
  const colaX = Math.max(30, Math.min(anchoVent-30, origenX-izqVent));
  const arribaVent = origen ? origen.bottom + 14 : 28;
  const haciaArriba = isMobile || (!!origen && origen.top > vh/2);
  const abajoMovil = origen ? Math.max(70, vh - origen.top + 12) : 80;
  // Arriba la ventana empieza debajo de la hora / la isla del iPhone y del difuminado que iOS 26 pone
  // un poco más abajo (zona segura × 1.55, igual que la barra de arriba).
  const topeArriba = `max(${isMobile ? 18 : 24}px, calc(env(safe-area-inset-top, 0px) * 1.55 + 10px))`;
  return (
      <div onClick={onCerrar} style={{ display:abierta?"block":"none", position:"fixed", inset:0, zIndex:900, background:"rgba(26,59,82,0.14)", overflowY:haciaArriba?"hidden":"auto" }}>
        <style>{`@keyframes ozenNube{from{transform:scale(.35);opacity:0}to{transform:scale(1);opacity:1}}`}</style>
        <div onClick={e=>e.stopPropagation()} style={{ position:haciaArriba?"fixed":"absolute", left:izqVent, width:anchoVent, ...(haciaArriba ? { bottom:abajoMovil, top:topeArriba, display:"flex", flexDirection:"column" } : { top:arribaVent, marginBottom:40 }), ...(isMobile
            // Celular: sin desenfoque en vivo (hacía lento el desplazamiento); fondo casi sólido.
            ? { background:"linear-gradient(160deg, rgba(255,255,255,0.98) 0%, rgba(248,244,240,0.97) 55%, rgba(255,255,255,0.97) 100%)" }
            : { background:"linear-gradient(160deg, rgba(255,255,255,0.62) 0%, rgba(246,240,235,0.48) 55%, rgba(255,255,255,0.40) 100%)", backdropFilter:"blur(26px) saturate(170%)", WebkitBackdropFilter:"blur(26px) saturate(170%)" }), border:"1px solid rgba(255,255,255,0.7)", borderRadius:22, boxShadow:"inset 0 1px 0 rgba(255,255,255,0.9), inset 0 -1px 0 rgba(255,255,255,0.25), 0 30px 80px -18px rgba(26,59,82,0.45)", animation:"ozenNube .3s cubic-bezier(.2,.9,.3,1.15)", transformOrigin: haciaArriba ? `${colaX}px calc(100% + 12px)` : `${colaX}px -12px` }}>
          {/* Colita de la nube, apuntando al + (curva suave, del mismo color de la ventana) */}
          <svg width="40" height="16" viewBox="0 0 40 16" aria-hidden="true" style={{ position:"absolute", left:colaX-20, ...(haciaArriba ? { bottom:-15 } : { top:-15, transform:"scaleY(-1)" }), overflow:"visible", filter:"drop-shadow(0 3px 3px rgba(26,59,82,0.12))" }}>
            <path d="M0 0 C12 0 15 12 20 16 C25 12 28 0 40 0 Z" fill={isMobile ? "#FEFDFC" : haciaArriba ? "rgba(250,246,242,0.78)" : "rgba(255,255,255,0.85)"}/>
          </svg>
          <div style={{ position:"relative", display:"grid", gridTemplateColumns:"1fr auto 1fr", alignItems:"center", gap:10, padding:isMobile?"10px 12px":"12px 20px", background:"linear-gradient(180deg, rgba(255,255,255,0.75), rgba(255,255,255,0.35))", borderBottom:"1px solid rgba(255,255,255,0.55)", borderRadius:"22px 22px 0 0", flexShrink:0 }}>
            <span style={{ display:"inline-flex", alignItems:"center", gap:10, minWidth:0 }}>
              <span style={{ width:32, height:32, borderRadius:"50%", background:C.gold, color:"#fff", display:"grid", placeItems:"center", flexShrink:0 }}><Icon n={icono} s={17} sw={2.6}/></span>
              {!isMobile && <b style={{ fontFamily:font.body, fontSize:17, color:C.text, whiteSpace:"nowrap" }}>{titulo}</b>}
            </span>
            <span style={{ display:"flex", justifyContent:"center" }}>{centro}</span>
            <span style={{ display:"flex", justifyContent:"flex-end" }}><button onClick={onCerrar} aria-label="Cerrar" title={tituloCerrar} style={{ width:36, height:36, borderRadius:10, border:`1px solid ${C.border}`, background:"#fff", color:C.text, display:"grid", placeItems:"center", cursor:"pointer" }}><Icon n="x" s={16} sw={2.4}/></button></span>
          </div>
          <div style={{ position:"relative", padding:isMobile?"14px":"20px 24px 26px", ...(haciaArriba ? { flex:1, overflowY:"auto", overscrollBehavior:"contain", WebkitOverflowScrolling:"touch" } : {}) }}>
            {children}
          </div>
        </div>
      </div>
  );
}

// Cuentas de tienda en computador (22 nov 2026): las pestañas van en una barra flotante abajo y
// centrada (como en el celular), con el + en el medio. Deja libre la parte de arriba.
function DockTienda({ tabs, tab, setTab }) {
  return (
    <div style={{ position:"fixed", left:"50%", bottom:16, transform:"translateX(-50%)", zIndex:60, display:"flex", alignItems:"center", gap:4, padding:"6px 10px", background:"#fff", border:`1px solid ${C.border}`, borderRadius:22, boxShadow:"0 14px 40px -14px rgba(26,59,82,0.35)" }}>
      {tabs.map(t=>{ const on = t.id===tab; if(esBotonMas(t.id)) return (
        <button key={t.id} onClick={(e)=>setTab(t.id, e.currentTarget.getBoundingClientRect())} aria-label={t.label} title={t.label} style={{ margin:"-22px 8px 0", width:58, height:58, borderRadius:"50%", border:"4px solid #fff", background:C.gold, color:"#fff", display:"grid", placeItems:"center", cursor:"pointer", boxShadow:"0 8px 20px -6px rgba(26,59,82,0.6)" }}><Icon n="plus" s={26} sw={2.6}/></button>
      ); return (
        <button key={t.id} onClick={()=>setTab(t.id)} style={{ display:"flex", flexDirection:"column", alignItems:"center", gap:3, minWidth:84, padding:"6px 10px", border:"none", borderRadius:14, background:on?C.surfaceHover:"transparent", color:on?C.goldDark:C.textMuted, cursor:"pointer", fontFamily:font.body }}>
          <Icon n={TAB_ICON[t.id]||"right"} s={20} sw={on?2:1.7}/>
          <span style={{ fontSize:11.5, fontWeight:on?700:500, whiteSpace:"nowrap" }}>{t.label}</span>
        </button>
      ); })}
    </div>
  );
}

// Campana única de avisos (22 nov 2026, decisión de Santiago: "una sola campana para todo"): va en
// la barra de arriba, junto al perfil, en todas las áreas, y junta lo que la persona puede ver:
// Flexipagos por recordarle al cliente (si ve la Lista de ventas), órdenes de clientes de
// Operaciones y solicitudes internas atrasadas (si ve Operaciones; las internas no para cuentas de
// tienda). Cuenta de tienda: solo lo de su tienda; las demás: todas.
function CampanaGeneral({ user, stores, tiendaIds, ventas, ventasItems, ventasAbonos, verFlex, ops, sols, onIrAOrden, onIrAFlexipago }) {
  const variasTiendas = tiendaIds.length>1;
  const flex = !verFlex ? [] : tiendaIds.flatMap(tid=>flexipagosPorVencer(tid, ventas, ventasItems, ventasAbonos, todayStr))
    .sort((a,b)=> a.vencido!==b.vencido ? (a.vencido?-1:1) : (a.diasRestantes60??999)-(b.diasRestantes60??999));
  return (
    <CampanaAvisos titulo="Avisos" grupos={[
      { titulo:"Flexipagos por recordarle al cliente", items:flex.map(({venta:v, saldoPendiente, diasRestantes60, vencido, fechaLimite})=>({
        key:`flex-${v.id}`, titulo:v.cliente_nombre||"Cliente sin nombre",
        onClick: onIrAFlexipago ? ()=>onIrAFlexipago(v) : undefined,
        accion:<FlexiAvisarWhatsApp venta={v} stores={stores} user={user} saldo={saldoPendiente} fechaLimite={fechaLimite} soloVer={esCuentaTienda(user) && v.tienda_id!==user.tienda_id}/>,
        sub:`${variasTiendas?`${nombreTiendaCorto(stores[v.tienda_id])} · `:""}${v.cliente_telefono?`Tel: ${v.cliente_telefono} · `:""}Debe ${fmtCOP(saldoPendiente)}`,
        badge:{ color:vencido?C.red:(diasRestantes60!==null && diasRestantes60<=5?C.amber:C.gold), label:vencido ? "⛔ Vencido" : `⏳ Vence en ${diasRestantes60}d` },
        urgente:vencido || (diasRestantes60!==null && diasRestantes60<=5),
      })) },
      { titulo:"Órdenes de clientes", items:operItemsCampana((ops||[]).filter(o=>operVisiblePara(o, user)), stores, onIrAOrden) },
      { titulo:"Solicitudes internas atrasadas", items:operItemsCampanaInt((sols||[]).filter(x=>operIntVisiblePara(x, user)), stores, onIrAOrden) },
    ]}/>
  );
}

function BottomNav({ tab, setTab, user, area, liderOper }) {
  const tabs = tabsPara(user, area, liderOper);
  return (
    <div style={{ display:"flex", borderTop:`1px solid ${C.border}`, background:"#fff", padding:"0 10px", paddingBottom:"max(12px, calc(env(safe-area-inset-bottom, 0px) + 4px))", flexShrink:0, position:"relative", zIndex:30 }}>
      {tabs.map(t => { const active=tab===t.id; if(esBotonMas(t.id)) return (
        <div key={t.id} style={{ flex:1, display:"flex", justifyContent:"center" }}>
          <button onClick={(e)=>setTab(t.id, e.currentTarget.getBoundingClientRect())} aria-label={t.label} style={{ marginTop:-18, width:58, height:58, borderRadius:"50%", border:"4px solid #fff", background:C.gold, color:"#fff", display:"grid", placeItems:"center", cursor:"pointer", boxShadow:"0 8px 20px -6px rgba(26,59,82,0.6)" }}><Icon n="plus" s={26} sw={2.6}/></button>
        </div>
      ); return (
        <button key={t.id} onClick={()=>setTab(t.id)} style={{ flex:1, padding:"10px 2px 6px", background:"none", border:"none", display:"flex", flexDirection:"column", alignItems:"center", gap:4, cursor:"pointer", color:active?C.goldDark:C.textMuted, position:"relative" }}>
          <span style={{ position:"absolute", top:0, left:"28%", right:"28%", height:2.5, borderRadius:2, background:active?C.gold:"transparent", transition:"background .25s ease" }}/>
          <Icon n={TAB_ICON[t.id]||"right"} s={23} sw={active?2:1.7}/>
          <div style={{ fontSize:11.5, fontFamily:font.body, fontWeight:active?700:500, lineHeight:1.1, textAlign:"center" }}>{t.label}</div>
        </button>
      ); })}
    </div>
  );
}

// ── Asistencia de hoy (cuadro en Turnos ▸ Malla) ───────────────────────────────
// Lo esencial de HOY: quién está, quién llegó tarde, quién falta y quién aún no llega.
// - Tarde: el MISMO cálculo de puntualidad de Registros (calcPuntualidad contra el turno publicado
//   de ese día si lo hay; si no, contra lo que marcó la persona; 5 min de gracia).
// - Falta: tiene turno publicado hoy (turnos_asignaciones, con tienda), no ha marcado NADA hoy y ya
//   pasó su hora de entrada (entrada_custom del día o la del horario vigente de su turno). Antes de
//   esa hora sale en "Aún no llegan". Si su turno no tiene horario definido, nunca sale como falta.
// No guarda nada ni cambia cómo se evalúa ninguna jornada: solo lee.
// Excusa de una llegada tarde (22 nov 2026, Santiago): solo deja de contar si está APROBADA. Una excusa
// no aprobada (o sin decidir) sigue siendo una tardanza sin excusa válida.
const excusaAprobada = (r) => !!r?.excusa_tarde && r.excusa_estado==="aprobada";
const minutosDeHHMM = (hhmm) => { if(!hhmm) return null; const [h,m]=hhmm.split(":").map(Number); return h*60+m; };
const resumenAsistenciaDia = (fecha, ahoraMin, records, users, turnosHorarios, turnosAsignaciones) => {
  const delDia = records.filter(r=>r.date===fecha);
  const nombreDe = (id, porDefecto) => users.find(u=>u.id===id)?.name || porDefecto || "—";
  const asigDe = (id) => (turnosAsignaciones||[]).find(a=>a.asesor_id===id && a.fecha===fecha);
  const cerro = (id) => delDia.some(r=>r.user_id===id && (r.event==="salida" || (r.event==="omitido" && r.time==="salida")));
  const enAlmuerzo = (id) => delDia.some(r=>r.user_id===id && r.event==="inicio_almuerzo") && !delDia.some(r=>r.user_id===id && (r.event==="fin_almuerzo" || (r.event==="omitido" && r.time==="fin_almuerzo")));
  // Una entrada por persona (la primera del día).
  const entradas = [];
  [...delDia].filter(r=>r.event==="entrada").sort((a,b)=>a.time.localeCompare(b.time)).forEach(r=>{ if(!entradas.some(e=>e.user_id===r.user_id)) entradas.push(r); });
  const conEntrada = entradas.map(r=>{
    const asig = asigDe(r.user_id);
    const shiftReal = asig?.tienda_id ? (asig.shift||r.shift) : r.shift;   // igual que Registros
    const storeReal = asig?.tienda_id || r.store;
    const punt = calcPuntualidad(r.time, shiftReal, fecha, storeReal, turnosHorarios, asig?.entrada_custom);
    return { id:r.user_id, nombre:nombreDe(r.user_id, r.user_name), store:r.store, entrada:r.time, punt, excusa:excusaAprobada(r), cerro:cerro(r.user_id), almuerzo:enAlmuerzo(r.user_id) };
  });
  const sinMarcar = [];
  (turnosAsignaciones||[]).filter(a=>a.fecha===fecha && a.tienda_id).forEach(a=>{
    if(sinMarcar.some(x=>x.id===a.asesor_id)) return;
    if(delDia.some(r=>r.user_id===a.asesor_id)) return;          // ya marcó algo hoy
    const esperada = a.entrada_custom ? minutosDeHHMM(a.entrada_custom) : getExpectedEntry(a.shift, fecha, a.tienda_id, turnosHorarios);
    sinMarcar.push({ id:a.asesor_id, nombre:nombreDe(a.asesor_id), store:a.tienda_id, shift:a.shift, esperada, falta: esperada!==null && esperada!==undefined && ahoraMin > esperada });
  });
  const porNombre = (a,b)=>a.nombre.localeCompare(b.nombre);
  return {
    enTurno: conEntrada.filter(p=>!p.cerro).sort(porNombre),
    tarde: conEntrada.filter(p=>p.punt && !p.punt.puntual && !p.excusa).sort((a,b)=>b.punt.diff-a.punt.diff),   // con excusa aprobada no cuenta
    faltan: sinMarcar.filter(p=>p.falta).sort((a,b)=>a.esperada-b.esperada),
    aunNo: sinMarcar.filter(p=>!p.falta).sort((a,b)=>(a.esperada??9999)-(b.esperada??9999)),
  };
};
const hhmmDeMinutos = (m) => `${String(Math.floor(m/60)).padStart(2,"0")}:${String(m%60).padStart(2,"0")}`;

// Cuadro "Asistencia de hoy" (22 nov 2026, pedido de Santiago): reemplaza la vista Resumen. Va en
// Turnos ▸ Malla, justo después de "Turnos y horarios", solo para quien tiene asistencia.panel.
// Cuatro columnas: Faltan · Llegaron tarde · En turno · Aún no llegan (reglas en resumenAsistenciaDia).
const ColumnaAsisHoy = ({ titulo, color, items, vacio }) => (
  <div style={{ background:"#fff", border:`1px solid ${C.border}`, borderTop:`3px solid ${color}`, borderRadius:12, padding:"10px 12px", minWidth:0 }}>
    <div style={{ display:"flex", alignItems:"baseline", gap:8, marginBottom:6 }}>
      <span style={{ fontFamily:font.mono, fontSize:22, fontWeight:700, color: items.length ? color : C.textMuted, lineHeight:1 }}>{items.length}</span>
      <span style={{ fontFamily:font.body, fontSize:12, fontWeight:700, color:C.text }}>{titulo}</span>
    </div>
    {items.length===0 ? <div style={{ fontFamily:font.body, fontSize:11.5, color:C.textMuted }}>{vacio}</div> :
      <div style={{ display:"flex", flexDirection:"column", gap:4 }}>
        {items.map(it=>(
          <div key={it.key} style={{ display:"flex", justifyContent:"space-between", gap:6, fontFamily:font.body, fontSize:12 }}>
            <span style={{ color:C.text, overflow:"hidden", textOverflow:"ellipsis", whiteSpace:"nowrap" }} title={it.titulo}>{it.nombre}</span>
            <span style={{ color:it.colorDato||C.textMuted, fontFamily:font.mono, fontSize:11, whiteSpace:"nowrap", flexShrink:0 }}>{it.dato}</span>
          </div>
        ))}
      </div>}
  </div>
);

function AsistenciaHoyCuadro({ records, stores, users, turnosHorarios, turnosAsignaciones }) {
  const isMobile = useIsMobile();
  // La hora avanza sola (cada minuto) para que alguien pase de "Aún no llega" a "Falta" sin recargar.
  const [ahora,setAhora]=useState(()=>toColombiaDate());
  useEffect(()=>{ const t=setInterval(()=>setAhora(toColombiaDate()), 60000); return ()=>clearInterval(t); },[]);
  const ahoraMin = ahora.getHours()*60+ahora.getMinutes();
  const { enTurno, tarde, faltan, aunNo } = resumenAsistenciaDia(todayStr, ahoraMin, records, users||[], turnosHorarios, turnosAsignaciones);
  const tienda = (id) => nombreTiendaCorto(stores[id]);
  const nom = (p) => isMobile ? primerNombre(p.nombre) : p.nombre;
  return (
    <SeccionTurnos titulo="Asistencia de hoy" nota={`a las ${fmtHora12(hhmmDeMinutos(ahoraMin))}`}>
      <div style={{ display:"grid", gridTemplateColumns:isMobile?"1fr 1fr":"repeat(4, minmax(0,1fr))", gap:10 }}>
        <ColumnaAsisHoy titulo="Faltan" color={C.red} vacio="Nadie pendiente después de su hora."
          items={faltan.map(p=>({ key:p.id, nombre:nom(p), titulo:`${p.nombre} · ${tienda(p.store)} · debía entrar ${fmtHora12(hhmmDeMinutos(p.esperada))}`, dato:`${ahoraMin-p.esperada} min`, colorDato:C.red }))}/>
        <ColumnaAsisHoy titulo="Llegaron tarde" color={C.amber} vacio="Nadie ha llegado tarde."
          items={tarde.map(p=>({ key:p.id, nombre:nom(p), titulo:`${p.nombre} · ${tienda(p.store)} · entró ${fmtHora12(p.entrada)}`, dato:`+${p.punt.diff} min`, colorDato:C.amber }))}/>
        <ColumnaAsisHoy titulo="En turno" color={C.green} vacio="Nadie en turno ahora."
          items={enTurno.map(p=>({ key:p.id, nombre:nom(p), titulo:`${p.nombre} · ${tienda(p.store)} · entrada ${fmtHora12(p.entrada)}`, dato:p.almuerzo ? "almuerzo" : tienda(p.store) }))}/>
        <ColumnaAsisHoy titulo="Aún no llegan" color={C.blue} vacio="Nadie más con turno hoy."
          items={aunNo.map(p=>({ key:p.id, nombre:nom(p), titulo:`${p.nombre} · ${tienda(p.store)}`, dato:p.esperada!==null && p.esperada!==undefined ? fmtHora12(hhmmDeMinutos(p.esperada)) : "sin horario" }))}/>
      </div>
    </SeccionTurnos>
  );
}

// ── SCREEN: Records ───────────────────────────────────────────────────────────
function RecordsScreen({ records, stores, users, isMobile, turnosHorarios, turnosAsignaciones, user, onRecordDeleted, onRecordUpdated }) {
  const [storeFilter, setStoreFilter] = useState("all");
  const [userFilter, setUserFilter]   = useState("all");
  const [dateFrom, setDateFrom]       = useState(todayStr);
  const [dateTo, setDateTo]           = useState(todayStr);
  const [viewPhoto, setViewPhoto]     = useState(null);
  // Corrección manual — solo master puede borrar un registro puntual (para que la persona lo
  // vuelva a marcar) o editar/crear directamente la hora de un evento (cuando ya pasó tiempo y no
  // tiene caso hacerla repetir el proceso completo con foto). Es una edición directa a la base de
  // datos, sin pasar por las validaciones normales del flujo de Marcar Asistencia — a propósito,
  // porque es Santiago corrigiendo un caso puntual que ya sabe que es real.
  const isMaster = puede(user, "asistencia.registros.corregir");   // Permisos, Fase 3 (el nombre se quedó de cuando era solo master)
  const [editingKey,setEditingKey]=useState(null),[editValue,setEditValue]=useState("");
  // Excusa de una llegada tarde (22 nov 2026): se guarda en la fila de "entrada" (registros.excusa_tarde
  // = motivo, registros.excusa_estado = "aprobada" | "no_aprobada"; ver sql/registros_excusa_tarde.sql).
  // Solo con excusa APROBADA la tardanza deja de contar en Informes y en "Asistencia de hoy".
  // Sin window.prompt (en algunos navegadores no sale): se escribe en un cuadrito dentro de la jornada.
  const [excusaEdit,setExcusaEdit]=useState(null); // { key, valor }
  // estado: "aprobada" | "no_aprobada" | null (quitar la excusa).
  const guardarExcusa=async(j, estado)=>{
    const texto=(excusaEdit?.valor||"").trim();
    if(estado && !texto){ alert("Escribe el motivo de la excusa."); return; }
    const{data,error}=await supabase.from("registros").update(estado ? { excusa_tarde:texto, excusa_estado:estado } : { excusa_tarde:null, excusa_estado:null }).eq("id",j.entrada.id).select().single();
    if(data){ onRecordUpdated(data); setExcusaEdit(null); } else if(error) alert(`No se pudo guardar la excusa: ${error.message}`);
  };
  const guardarHora=async(j,eventKey,existingId)=>{
    if(!editValue) return;
    if(existingId){
      const{data,error}=await supabase.from("registros").update({event:eventKey,time:editValue}).eq("id",existingId).select().single();
      if(data){ onRecordUpdated(data); setEditingKey(null); } else if(error){ alert(`No se pudo guardar: ${error.message}`); }
    } else {
      const{data,error}=await supabase.from("registros").insert({user_id:j.userId,user_name:j.userName,store:j.store,shift:j.shift,event:eventKey,date:j.date,time:editValue,photo_url:null}).select().single();
      if(data){ onRecordUpdated(data); setEditingKey(null); } else if(error){ alert(`No se pudo guardar: ${error.message}`); }
    }
  };
  const eliminarRegistro=async(id,descripcion)=>{
    if(!await confirmar(`¿Eliminar ${descripcion}? La persona podrá volver a marcarlo (o usa "✏️" para dejarlo con la hora correcta sin borrarlo).`)) return;
    const{error}=await supabase.from("registros").delete().eq("id",id);
    if(!error) onRecordDeleted(id); else alert(`No se pudo eliminar: ${error.message}`);
  };

  // El filtro de personas se arma con quien REALMENTE tiene registros guardados (sacado directo de
  // `records`, que ya trae el nombre) — no con `users` filtrado a rol "Asesor". Antes, si alguien
  // cambiaba de rol, se desactivaba, o cualquier cuenta que no fuera exactamente "advisor" marcaba
  // asistencia (master, admin_turnos, etc. también pueden marcar la suya propia), esa persona
  // desaparecía del filtro aunque sus registros de días anteriores siguieran ahí — imposible de
  // filtrar aunque los datos existieran.
  const advisors = Object.values(
    records.reduce((acc,r)=>{ if(!acc[r.user_id]) acc[r.user_id]={ id:r.user_id, name:r.user_name }; return acc; }, {})
  ).sort((a,b)=>a.name.localeCompare(b.name));

  const filtered = records
    .filter(r=>storeFilter==="all"||r.store===storeFilter)
    .filter(r=>userFilter==="all"||r.user_id===userFilter)
    .filter(r=>(!dateFrom||r.date>=dateFrom)&&(!dateTo||r.date<=dateTo));

  const jornadasMap = {};
  filtered.forEach(r=>{
    const key=`${r.user_id}_${r.date}`;
    if(!jornadasMap[key]) jornadasMap[key]={ key, userId:r.user_id, userName:r.user_name, store:r.store, shift:r.shift, date:r.date, entrada:null, inicio_almuerzo:null, fin_almuerzo:null, salida:null };
    if(r.event!=="omitido") jornadasMap[key][r.event]=r;
    else jornadasMap[key][r.time+"_omitido"]=r; // se guarda la fila completa (no solo `true`) para poder borrarla/editarla
  });
  const jornadas = Object.values(jornadasMap).sort((a,b)=>b.date.localeCompare(a.date)||a.userName.localeCompare(b.userName));

  const EventBlock = ({ label, eventKey, jornada, registro, omitido, color, desvio }) => {
    const isOmitido = !registro && omitido;
    const existingId = registro?.id || (isOmitido ? omitido.id : null);
    const editKey = `${jornada.key}::${eventKey}`;
    const editando = isMaster && editingKey===editKey;
    return (
      <div style={{ flex:1, minWidth:0, borderRadius:8, padding:"8px 4px", background:isOmitido?`${C.red}18`:C.surfaceAlt, border:`1px solid ${isOmitido?C.red+"44":C.border}`, display:"flex", flexDirection:"column", alignItems:"center", gap:6 }}>
        <div style={{ fontFamily:font.body, fontSize:9, color:C.textMuted, textTransform:"uppercase", letterSpacing:"0.05em", textAlign:"center", lineHeight:1.2 }}>{label}</div>
        {editando ? (
          <input type="time" autoFocus value={editValue} onChange={e=>setEditValue(e.target.value)} style={{ width:62, background:C.dark, border:`1px solid ${C.gold}`, borderRadius:5, padding:"2px 3px", color:C.text, fontSize:11, fontFamily:font.mono, outline:"none" }} />
        ) : (
          <div style={{ display:"flex", alignItems:"baseline", gap:2 }}>
            {/* El N/R ahora también muestra a qué hora quedó marcado (created_at, no `time` — en un
                N/R `time` guarda CUÁL evento se saltó, no una hora real) — así se puede explicar
                "pasaron 2 horas y no marcaste" o "se marcó a tal hora porque nunca marcaste salida". */}
            <span style={{ fontFamily:font.mono, fontSize:12, color:isOmitido?C.red:registro?color:C.border, fontWeight:700 }}>{registro?registro.time:isOmitido?`N/R ${fmtTime(new Date(omitido.created_at))}`:"—"}</span>
            {/* +N/-N sutil junto a la hora de Fin Almuerzo — cuánto se pasó (o no) del tiempo de almuerzo permitido. */}
            {desvio!==null && desvio!==undefined && desvio!==0 && <span style={{ fontFamily:font.mono, fontSize:9, fontWeight:700, color:desvio>0?C.amber:C.textMuted }}>{desvio>0?`+${desvio}`:desvio}</span>}
          </div>
        )}
        <div style={{ width:36, height:36, borderRadius:6, overflow:"hidden", border:`1px solid ${C.border}`, background:C.dark, display:"flex", alignItems:"center", justifyContent:"center", flexShrink:0 }}>
          {registro?.photo_url
            ? <img src={registro.photo_url} onClick={()=>setViewPhoto(registro.photo_url)} alt="foto" style={{ width:"100%", height:"100%", objectFit:"cover", cursor:"pointer", display:"block" }} />
            : <span style={{ fontSize:12, opacity:0.25 }}>📷</span>
          }
        </div>
        {/* Solo lectura acá — quien administra ve el comentario (si existe) pero no lo agrega ni lo
            edita, eso es solo del dueño del registro (ver ComentarioRegistro). */}
        {registro && <ComentarioRegistro registro={registro} editable={false}/>}
        {/* Editar convierte un N/R en un registro real sin foto (una reconstrucción tuya, no lo que
            la persona realmente hizo), y borrar un N/R ya no debería hacer falta seguido ahora que
            los cron de Supabase evitan que se generen mal — por eso ninguno de los dos botones se
            ofrece sobre una fila en N/R. Si de verdad hay que tocar un N/R puntual, se hace directo
            en Supabase (con más cuidado, a propósito). Sobre un registro real o un espacio vacío
            ("—") sí se puede editar/crear/eliminar normal. */}
        {isMaster && !isOmitido && (
          editando ? (
            <div style={{ display:"flex", gap:4 }}>
              <button onClick={()=>guardarHora(jornada,eventKey,existingId)} title="Guardar" style={{ background:"none", border:`1px solid ${C.green}`, color:C.green, borderRadius:5, padding:"1px 6px", fontSize:10, cursor:"pointer" }}>✓</button>
              <button onClick={()=>setEditingKey(null)} title="Cancelar" style={{ background:"none", border:"none", color:C.textMuted, cursor:"pointer", fontSize:10 }}>✕</button>
            </div>
          ) : (
            <div style={{ display:"flex", gap:4 }}>
              <button onClick={()=>{ setEditingKey(editKey); setEditValue(registro?.time||"12:00"); }} title="Editar / crear hora" style={{ background:"none", border:"none", color:C.textMuted, cursor:"pointer", fontSize:10 }}>✏️</button>
              {existingId && <button onClick={()=>eliminarRegistro(existingId, `${label} de ${jornada.userName}`)} title="Eliminar" style={{ background:"none", border:"none", color:C.red, cursor:"pointer", fontSize:10 }}>🗑</button>}
            </div>
          )
        )}
      </div>
    );
  };

  return (
    <div>
      {viewPhoto && (
        <div onClick={()=>setViewPhoto(null)} style={{ position:"fixed", inset:0, background:"rgba(0,0,0,0.9)", display:"flex", alignItems:"center", justifyContent:"center", zIndex:400, cursor:"pointer", padding:16 }}>
          <img src={viewPhoto} alt="Foto" style={{ maxWidth:"100%", maxHeight:"90vh", borderRadius:10 }} />
        </div>
      )}
      <PageHeader title="Registros" subtitle={`${jornadas.length} jornadas`} />
      <Card style={{ marginBottom:12, overflow:"hidden" }} p="12px">
        <div style={{ display:"grid", gridTemplateColumns:"1fr 1fr", gap:8, marginBottom:8, width:"100%" }}>
          <div style={{ minWidth:0 }}>
            <div style={{ fontSize:10, color:C.textMuted, fontFamily:font.body, textTransform:"uppercase", letterSpacing:"0.07em", marginBottom:4 }}>Desde</div>
            <input type="date" value={dateFrom} onChange={e=>setDateFrom(e.target.value)} style={{ width:"100%", minWidth:0, background:C.surfaceAlt, border:`1px solid ${C.border}`, borderRadius:7, padding:"7px 8px", color:C.text, fontSize:12, fontFamily:font.body, outline:"none", boxSizing:"border-box", WebkitAppearance:"none", appearance:"none" }} />
          </div>
          <div style={{ minWidth:0 }}>
            <div style={{ fontSize:10, color:C.textMuted, fontFamily:font.body, textTransform:"uppercase", letterSpacing:"0.07em", marginBottom:4 }}>Hasta</div>
            <input type="date" value={dateTo} onChange={e=>setDateTo(e.target.value)} style={{ width:"100%", minWidth:0, background:C.surfaceAlt, border:`1px solid ${C.border}`, borderRadius:7, padding:"7px 8px", color:C.text, fontSize:12, fontFamily:font.body, outline:"none", boxSizing:"border-box", WebkitAppearance:"none", appearance:"none" }} />
          </div>
        </div>
        <div style={{ display:"grid", gridTemplateColumns:"1fr 1fr auto", gap:8 }}>
          <select value={userFilter} onChange={e=>setUserFilter(e.target.value)} style={{ background:C.surfaceAlt, border:`1px solid ${C.border}`, borderRadius:7, padding:"7px 8px", color:C.text, fontSize:11, fontFamily:font.body, outline:"none", width:"100%" }}>
            <option value="all">Todos los asesores</option>
            {advisors.map(u=><option key={u.id} value={u.id}>{u.name}</option>)}
          </select>
          <select value={storeFilter} onChange={e=>setStoreFilter(e.target.value)} style={{ background:C.surfaceAlt, border:`1px solid ${C.border}`, borderRadius:7, padding:"7px 8px", color:C.text, fontSize:11, fontFamily:font.body, outline:"none", width:"100%" }}>
            <option value="all">Todas las tiendas</option>
            {Object.values(stores).map(s=><option key={s.id} value={s.id}>{s.name}</option>)}
          </select>
          <Btn onClick={()=>{ setDateFrom(todayStr); setDateTo(todayStr); setUserFilter("all"); setStoreFilter("all"); }} variant="ghost" sm>Hoy</Btn>
        </div>
      </Card>

      <div style={{ display:"flex", flexDirection:"column", gap:10 }}>
        {jornadas.map(j=>{
          const asigDia=(turnosAsignaciones||[]).find(a=>a.asesor_id===j.userId&&a.fecha===j.date);
          // Si hay un turno oficial asignado en el Borrador para ese día, la puntualidad se
          // evalúa contra ESE (aunque la persona haya marcado otro por error) — no contra lo
          // autorreportado. Si no hay asignación (o es un turno especial sin tienda), se usa lo
          // que quedó en el registro, como antes.
          const shiftReal = asigDia?.tienda_id ? (asigDia.shift||j.shift) : j.shift;
          const storeReal = asigDia?.tienda_id || j.store;
          const punt=calcPuntualidad(j.entrada?.time,shiftReal,j.date,storeReal,turnosHorarios,asigDia?.entrada_custom);
          const rango=getExpectedRange(shiftReal,j.date,storeReal,turnosHorarios,asigDia?.entrada_custom,asigDia?.salida_custom);
          return (
            <Card key={j.key} p="14px">
              <div style={{ marginBottom:10 }}>
                <div style={{ display:"flex", alignItems:"center", justifyContent:"space-between", gap:8, marginBottom:4 }}>
                  <div style={{ fontFamily:font.body, fontSize:13, fontWeight:600, color:C.text, overflow:"hidden", textOverflow:"ellipsis", whiteSpace:"nowrap", flex:1 }}>{j.userName}</div>
                  {punt && (punt.puntual ? <Badge color={C.green} sm>🟢 Puntual</Badge> : excusaAprobada(j.entrada)
                    ? <Badge color={C.textMuted} sm title={`Excusa aprobada: ${j.entrada.excusa_tarde}`}>🟡 Tarde {punt.diff} min · excusa aprobada</Badge>
                    : j.entrada?.excusa_tarde
                    ? <Badge color={C.red} sm title={`Excusa NO aprobada: ${j.entrada.excusa_tarde}`}>🔴 Tarde {punt.diff} min · excusa no aprobada</Badge>
                    : <Badge color={C.red} sm>🔴 Tarde {punt.diff} min</Badge>)}
                  {punt && !punt.puntual && isMaster && j.entrada && <button onClick={()=>setExcusaEdit({ key:j.key, valor:j.entrada.excusa_tarde||"" })} title={j.entrada.excusa_tarde?`Excusa: ${j.entrada.excusa_tarde} (clic para cambiar la decisión o quitarla)`:"Registrar una excusa y decidir si se aprueba (solo aprobada deja de contar)"} style={{ background:"none", border:`1px solid ${C.border}`, borderRadius:6, padding:"2px 8px", fontFamily:font.body, fontSize:11, color:C.textSub, cursor:"pointer", whiteSpace:"nowrap" }}>{j.entrada.excusa_tarde?"Excusa":"Excusar"}</button>}
                </div>
                <div style={{ fontFamily:font.body, fontSize:10, color:C.textMuted, overflow:"hidden", textOverflow:"ellipsis", whiteSpace:"nowrap" }}>{stores[j.store]?.name} · {j.shift} · {j.date}{rango?` - ${rango}`:""}</div>
                {excusaEdit?.key===j.key && (
                  <div style={{ display:"flex", gap:6, alignItems:"center", marginTop:8, flexWrap:"wrap" }}>
                    <input autoFocus value={excusaEdit.valor} onChange={e=>setExcusaEdit({ key:j.key, valor:e.target.value })} onKeyDown={e=>{ if(e.key==="Escape") setExcusaEdit(null); }} placeholder="Motivo de la excusa" style={{ flex:1, minWidth:180, background:C.surfaceAlt, border:`1px solid ${C.border}`, borderRadius:7, padding:"6px 9px", fontFamily:font.body, fontSize:12, color:C.text, outline:"none" }}/>
                    <Btn onClick={()=>guardarExcusa(j, "aprobada")} sm>✓ Aprobar</Btn>
                    <Btn onClick={()=>guardarExcusa(j, "no_aprobada")} variant="danger" sm>✕ No aprobar</Btn>
                    {j.entrada.excusa_tarde && <Btn onClick={()=>guardarExcusa(j, null)} variant="ghost" sm>Quitar excusa</Btn>}
                    <Btn onClick={()=>setExcusaEdit(null)} variant="ghost" sm>Cancelar</Btn>
                  </div>
                )}
              </div>
              <div style={{ display:"flex", gap:6 }}>
                <EventBlock label="Entrada"       eventKey="entrada"        jornada={j} registro={j.entrada}        omitido={j["entrada_omitido"]}        color={C.green} />
                <EventBlock label="Ini. Almuerzo" eventKey="inicio_almuerzo" jornada={j} registro={j.inicio_almuerzo} omitido={j["inicio_almuerzo_omitido"]} color={C.amber} />
                <EventBlock label="Fin Almuerzo"  eventKey="fin_almuerzo"   jornada={j} registro={j.fin_almuerzo}   omitido={j["fin_almuerzo_omitido"]}   color={C.blue}  desvio={calcDesvioAlmuerzo(j.inicio_almuerzo?.time, j.fin_almuerzo?.time)} />
                <EventBlock label="Salida"        eventKey="salida"         jornada={j} registro={j.salida}         omitido={j["salida_omitido"]}         color={C.red}   />
              </div>
            </Card>
          );
        })}
        {jornadas.length===0 && <div style={{ textAlign:"center", padding:40, color:C.textMuted, fontFamily:font.body, fontSize:13 }}>Sin registros para los filtros seleccionados.</div>}
      </div>
    </div>
  );
}

// ── Retirar en vez de eliminar (pedido de Santiago) ─────────────────────────────
// Antes "Eliminar" borraba también los turnos, la asistencia y la meta de la persona, y ese
// historial se perdía para siempre (ej. al revisar la malla de un mes pasado ya no aparecía). Ahora:
// si la persona tiene CUALQUIER historial, no se elimina — se RETIRA (queda inactiva: no puede
// ingresar ni aparece para asignar, pero todo su historial se conserva y la malla de los meses en
// que trabajó la sigue mostrando). Solo se elimina de verdad quien no tiene nada (ej. creado por error).
const contarHistorialUsuario = async (id) => {
  const contar = async (tabla, campo) => { const { count, error } = await supabase.from(tabla).select("id", { count:"exact", head:true }).eq(campo, id); return error ? 0 : (count||0); };
  const [registros, turnos, ventas, metas] = await Promise.all([
    contar("registros","user_id"), contar("turnos_asignaciones","asesor_id"), contar("ventas","vendedor_id"), contar("ventas_metas_asesor","vendedor_id"),
  ]);
  return { registros, turnos, ventas, metas, total: registros+turnos+ventas+metas };
};
const textoHistorial = (h) => [
  h.turnos ? `${h.turnos} turno${h.turnos===1?"":"s"} en la malla` : null,
  h.registros ? `${h.registros} registro${h.registros===1?"":"s"} de asistencia` : null,
  h.ventas ? `${h.ventas} venta${h.ventas===1?"":"s"}` : null,
  h.metas ? `${h.metas} meta${h.metas===1?"":"s"} de ventas` : null,
].filter(Boolean).join(", ");
const retirarOEliminarUsuario = async (u, setUsers) => {
  const h = await contarHistorialUsuario(u.id);
  if(h.total>0){
    if(u.active===false){ alert(`${u.name} ya está retirado. Su historial (${textoHistorial(h)}) se conserva; no se puede eliminar para no perderlo.`); return; }
    if(!await confirmar(`${u.name} tiene historial: ${textoHistorial(h)}.\n\nPara no perderlo no se elimina: se RETIRA. Queda inactivo (no puede ingresar ni aparece para asignar), pero sus turnos, asistencia y ventas se conservan y se siguen viendo en los meses en que trabajó. Si vuelve, lo reactivas con ✓.\n\n¿Retirar a ${u.name}?`)) return;
    const { data, error } = await supabase.from("usuarios").update({ active:false }).eq("id", u.id).select().single();
    if(error){ alert(`No se pudo retirar: ${error.message}`); return; }
    if(data) setUsers(prev=>prev.map(x=>x.id===u.id?data:x));
    return;
  }
  if(!await confirmar(`${u.name} no tiene ningún historial (ni turnos, ni asistencia, ni ventas). ¿Eliminarlo definitivamente? Esto no se puede deshacer.`)) return;
  await supabase.from("turnos_borrador").delete().eq("asesor_id", u.id);
  const { error } = await supabase.from("usuarios").delete().eq("id", u.id);
  if(error){ alert(`No se pudo eliminar: ${error.message}`); return; }
  setUsers(prev=>prev.filter(x=>x.id!==u.id));
};
// Encabezado plegable de la sección de retirados / inactivos en Usuarios y Asesores.
const SeccionRetirados = ({ n, abierto, onToggle }) => (
  <button onClick={onToggle} style={{ display:"flex", alignItems:"center", gap:8, marginTop:14, padding:"10px 14px", width:"100%", border:`1px dashed ${C.border}`, borderRadius:12, background:"transparent", cursor:"pointer", fontFamily:font.body, fontSize:13, fontWeight:600, color:C.textSub, textAlign:"left" }}>
    <Icon n={abierto?"up":"down"} s={14} sw={2.2}/>Retirados e inactivos ({n})
    <span style={{ marginLeft:"auto", fontWeight:400, fontSize:12, color:C.textMuted }}>su historial se conserva</span>
  </button>
);

// ── SCREEN: Users ─────────────────────────────────────────────────────────────
function UsersScreen({ users, setUsers }) {
  const soloLectura = useReadOnly();
  const [showForm,setShowForm]=useState(false),[form,setForm]=useState({name:"",documento:""}),[editing,setEditing]=useState(null),[editVal,setEditVal]=useState({}),[loading,setLoading]=useState(false);
  const advisors=users.filter(u=>u.role==="advisor");
  const add=async()=>{ if(!form.name.trim()||!form.documento.trim())return; setLoading(true); const{data,error}=await supabase.from("usuarios").insert({name:form.name.trim(),documento:form.documento.trim(),password:form.documento.trim(),role:"advisor",active:true}).select().single(); if(!error){setUsers(prev=>[...prev,data]);setForm({name:"",documento:""});setShowForm(false);} setLoading(false); };
  const toggle=async(u)=>{ const{data}=await supabase.from("usuarios").update({active:!u.active}).eq("id",u.id).select().single(); if(data)setUsers(prev=>prev.map(x=>x.id===u.id?data:x)); };
  const saveEdit=async(id)=>{ if(!editVal.name.trim()||!editVal.documento.trim())return; const{data}=await supabase.from("usuarios").update({name:editVal.name.trim(),documento:editVal.documento.trim()}).eq("id",id).select().single(); if(data){setUsers(prev=>prev.map(u=>u.id===id?data:u));setEditing(null);} };
  const deleteUser=async(id)=>{ const u = users.find(x=>x.id===id); if(u) await retirarOEliminarUsuario(u, setUsers); };
  const [verRetirados,setVerRetirados]=useState(false);
  const tarjetaAsesor = (u) => (
          <Card key={u.id} p="14px" style={{opacity:u.active?1:0.6}}>
            {!soloLectura && editing===u.id?(
              <div><Field label="Nombre" value={editVal.name} onChange={v=>setEditVal(p=>({...p,name:v}))} /><Field label="Usuario" value={editVal.documento} onChange={v=>setEditVal(p=>({...p,documento:v}))} /><div style={{display:"flex",gap:8}}><Btn onClick={()=>saveEdit(u.id)} variant="success" sm full>Guardar</Btn><Btn onClick={()=>setEditing(null)} variant="ghost" sm full>Cancelar</Btn></div></div>
            ):(
              <div style={{display:"flex",alignItems:"center",gap:10}}>
                <div style={{width:36,height:36,borderRadius:8,background:C.gold,display:"flex",alignItems:"center",justifyContent:"center",fontFamily:font.body,fontWeight:700,color:"#fff",flexShrink:0}}>{u.name[0]}</div>
                <div style={{flex:1,minWidth:0}}><div style={{fontFamily:font.body,fontSize:13,color:C.text,fontWeight:500,overflow:"hidden",textOverflow:"ellipsis",whiteSpace:"nowrap"}}>{u.name}</div><div style={{fontFamily:font.mono,fontSize:11,color:C.textMuted}}>{u.documento}</div></div>
                <Badge color={u.active?C.green:C.red} sm>{u.active?"Activo":"Inactivo"}</Badge>
                {!soloLectura && <div style={{display:"flex",gap:4,flexShrink:0}}>
                  <Btn onClick={()=>{setEditing(u.id);setEditVal({name:u.name,documento:u.documento});}} variant="ghost" sm>✏</Btn>
                  <Btn onClick={()=>toggle(u)} variant={u.active?"danger":"success"} sm>{u.active?"✕":"✓"}</Btn>
                  <Btn onClick={()=>deleteUser(u.id)} variant="danger" sm title="Retirar (o eliminar si no tiene historial)">🗑</Btn>
                </div>}
              </div>
            )}
          </Card>
  );
  return (
    <div>
      <PageHeader title="Asesores" subtitle={`${advisors.length} asesores`} action={soloLectura?null:<Btn onClick={()=>{setShowForm(!showForm);setEditing(null);}} sm>{showForm?"Cancelar":"+ Nuevo"}</Btn>} />
      {!soloLectura && showForm&&(<Card glow style={{marginBottom:16}}><div style={{fontFamily:font.body,fontSize:13,fontWeight:600,color:C.goldLight,marginBottom:14}}>Nuevo asesor</div><Field label="Nombre completo" value={form.name} onChange={v=>setForm(f=>({...f,name:v}))} placeholder="Nombre Apellido" /><Field label="Usuario" value={form.documento} onChange={v=>setForm(f=>({...f,documento:v}))} placeholder="Usuario para ingresar" /><div style={{fontFamily:font.body,fontSize:11,color:C.textMuted,marginBottom:12}}>💡 La contraseña inicial será el mismo usuario.</div><Btn onClick={add} disabled={loading} full>{loading?"Guardando...":"Crear asesor"}</Btn></Card>)}
      <div style={{display:"flex",flexDirection:"column",gap:8}}>
        {advisors.filter(u=>u.active).map(tarjetaAsesor)}
        {advisors.some(u=>!u.active) && <SeccionRetirados n={advisors.filter(u=>!u.active).length} abierto={verRetirados} onToggle={()=>setVerRetirados(v=>!v)}/>}
        {verRetirados && advisors.filter(u=>!u.active).map(tarjetaAsesor)}
      </div>
    </div>
  );
}

// ── SCREEN: Usuarios (solo master) ─────────────────────────────────────────────
const ROLE_LABEL = { master:"Master", admin:"Administrador", admin_finanzas:"Admin Finanzas", admin_turnos:"Admin Turnos", visualizador:"Visualizador", advisor:"Asesor", tienda:"Cuenta de tienda" };
const ROLE_COLOR = { master:C.red, admin:C.gold, admin_finanzas:C.blue, admin_turnos:C.green, visualizador:C.amber, advisor:C.blue, tienda:C.textMuted };
const ROLE_PERMISOS = {
  master: "Acceso total: Asistencia, Junta, Ventas y el módulo de Usuarios (ve y cambia todas las contraseñas).",
  admin: "Asistencia y Junta completos (panel, registros, informes); en Turnos solo puede ver la malla. En Ventas solo puede ver (lista, métricas, caja, y la pantalla de Registrar para ver cómo funciona) — no puede guardar ni corregir nada.",
  admin_finanzas: "Todo lo de un Administrador (Asistencia y Junta), más Ventas completo: registrar, lista, métricas, asignar metas, aprobar notas crédito y corregir por error.",
  admin_turnos: "Todo lo de un Administrador (Asistencia y Junta, Ventas solo lectura), más acceso completo a Turnos: editar el Borrador, publicar y entrar a Administrar (crear/editar/retirar asesores, tiendas, turnos especiales, horarios).",
  visualizador: "Puede ver Asistencia, Junta y Ventas, sin poder editar ni registrar nada en ninguno de los tres. Lo único propio que hace: marcar su asistencia y firmar documentos.",
  advisor: "Marca su propia asistencia y ve su historial/malla. Si se usa para vender, aparece para elegir como quién hizo la venta.",
  tienda: "Login compartido de una tienda: solo entra a Ventas (Registrar, Lista, Métricas, Caja) de esa tienda, con la fecha fija en hoy.",
};
function UsuariosScreen({ users, setUsers, stores }) {
  const [showForm,setShowForm]=useState(false),[form,setForm]=useState({name:"",documento:"",role:"advisor",tienda_id:""}),[editing,setEditing]=useState(null),[editVal,setEditVal]=useState({}),[cambiandoPass,setCambiandoPass]=useState(null),[nuevaPass,setNuevaPass]=useState(""),[loading,setLoading]=useState(false);
  const tiendaOptions=[{value:"",label:"Selecciona una tienda..."}, ...tiendasVenta(stores).map(s=>({value:s.id,label:s.name}))];
  const [passVisible,setPassVisible]=useState({});
  const [sincronizando,setSincronizando]=useState(false);
  const traerFrescos=async()=>{ setSincronizando(true); const{data}=await supabase.from("usuarios").select("*"); if(data)setUsers(data); setSincronizando(false); };
  // Cada vez que se entra a esta pestaña, trae los datos más recientes de la base de
  // datos — así si alguien cambió su propia contraseña desde otra sesión, aparece
  // aquí sin que master tenga que adivinar o darle refrescar manualmente.
  useEffect(()=>{ traerFrescos(); },[]);
  const ordenRol = (r) => r==="master"?0 : (r==="admin"||r==="admin_turnos")?1 : 2;
  const ordenados=[...users].sort((a,b)=>ordenRol(a.role)-ordenRol(b.role) || a.name.localeCompare(b.name));
  const roleOptions=[{value:"advisor",label:"Asesor"},{value:"admin",label:"Administrador"},{value:"admin_finanzas",label:"Admin Finanzas"},{value:"admin_turnos",label:"Admin Turnos"},{value:"visualizador",label:"Visualizador"},{value:"tienda",label:"Cuenta de tienda"},{value:"master",label:"Master"}];
  const add=async()=>{ if(!form.name.trim()||!form.documento.trim())return; if(form.role==="tienda"&&!form.tienda_id)return; setLoading(true); const{data,error}=await supabase.from("usuarios").insert({name:form.name.trim(),documento:form.documento.trim(),password:form.documento.trim(),role:form.role,tienda_id:form.role==="tienda"?form.tienda_id:null,active:true}).select().single(); if(!error&&data){setUsers(prev=>[...prev,data]);setForm({name:"",documento:"",role:"advisor",tienda_id:""});setShowForm(false);} setLoading(false); };
  const toggle=async(u)=>{ const{data}=await supabase.from("usuarios").update({active:!u.active}).eq("id",u.id).select().single(); if(data)setUsers(prev=>prev.map(x=>x.id===u.id?data:x)); };
  const saveEdit=async(id)=>{ if(!editVal.name.trim()||!editVal.documento.trim())return; if(editVal.role==="tienda"&&!editVal.tienda_id)return; const{data}=await supabase.from("usuarios").update({name:editVal.name.trim(),documento:editVal.documento.trim(),role:editVal.role,tienda_id:editVal.role==="tienda"?(editVal.tienda_id||null):null}).eq("id",id).select().single(); if(data){setUsers(prev=>prev.map(u=>u.id===id?data:u));setEditing(null);} };
  const deleteUsuario=async(id)=>{ const u = users.find(x=>x.id===id); if(u) await retirarOEliminarUsuario(u, setUsers); };
  const [verRetirados,setVerRetirados]=useState(false);
  const guardarPassword=async(id)=>{ if(!nuevaPass.trim())return; const{data,error}=await supabase.from("usuarios").update({password:nuevaPass.trim(),password_updated_at:new Date().toISOString()}).eq("id",id).select().single(); if(!error&&data){setUsers(prev=>prev.map(u=>u.id===id?data:u));setCambiandoPass(null);setNuevaPass("");alert("Contraseña actualizada.");} };
  const liberarDispositivo=async(u)=>{ if(!await confirmar(`¿Liberar el dispositivo autorizado de "${u.name}"? El próximo dispositivo que ingrese con esta cuenta quedará autorizado.`))return; const{data}=await supabase.from("usuarios").update({device_token:null}).eq("id",u.id).select().single(); if(data)setUsers(prev=>prev.map(x=>x.id===u.id?data:x)); };
  const tarjetaUsuario = (u) => (
          <Card key={u.id} p="14px" style={{opacity:u.active?1:0.6}}>
            {editing===u.id?(
              <div>
                <Field label="Nombre" value={editVal.name} onChange={v=>setEditVal(p=>({...p,name:v}))} />
                <Field label="Usuario" value={editVal.documento} onChange={v=>setEditVal(p=>({...p,documento:v}))} />
                <Field label="Tipo de usuario" value={editVal.role} onChange={v=>setEditVal(p=>({...p,role:v}))} options={roleOptions} />
                <div style={{fontFamily:font.body,fontSize:11,color:C.textMuted,marginTop:-10,marginBottom:12}}>🔎 {ROLE_PERMISOS[editVal.role]}</div>
                {editVal.role==="tienda" && <Field label="Tienda de esta cuenta" value={editVal.tienda_id||""} onChange={v=>setEditVal(p=>({...p,tienda_id:v}))} options={tiendaOptions} />}
                <div style={{display:"flex",gap:8}}><Btn onClick={()=>saveEdit(u.id)} disabled={editVal.role==="tienda" && !editVal.tienda_id} variant="success" sm full>Guardar</Btn><Btn onClick={()=>setEditing(null)} variant="ghost" sm full>Cancelar</Btn></div>
              </div>
            ):cambiandoPass===u.id?(
              <div>
                <Field label={`Nueva contraseña para ${u.name}`} type="password" value={nuevaPass} onChange={setNuevaPass} placeholder="Nueva contraseña" autoComplete="new-password" />
                <div style={{display:"flex",gap:8}}><Btn onClick={()=>guardarPassword(u.id)} variant="success" sm full>Guardar contraseña</Btn><Btn onClick={()=>{setCambiandoPass(null);setNuevaPass("");}} variant="ghost" sm full>Cancelar</Btn></div>
              </div>
            ):(
              <div style={{display:"flex",alignItems:"center",gap:10,flexWrap:"wrap"}}>
                <div style={{width:36,height:36,borderRadius:8,background:C.gold,display:"flex",alignItems:"center",justifyContent:"center",fontFamily:font.body,fontWeight:700,color:"#fff",flexShrink:0}}>{u.name[0]}</div>
                <div style={{flex:1,minWidth:120}}><div style={{fontFamily:font.body,fontSize:13,color:C.text,fontWeight:500,overflow:"hidden",textOverflow:"ellipsis",whiteSpace:"nowrap"}}>{u.name}</div><div style={{fontFamily:font.mono,fontSize:11,color:C.textMuted}}>{u.documento}</div></div>
                <Badge color={ROLE_COLOR[u.role]||C.textMuted} sm title={ROLE_PERMISOS[u.role]}>{ROLE_LABEL[u.role]||u.role}</Badge>
                {u.role==="tienda" && <Badge color={C.textMuted} sm>{stores[u.tienda_id]?.name || "Sin tienda asignada"}</Badge>}
                <Badge color={u.active?C.green:C.red} sm>{u.active?"Activo":"Inactivo"}</Badge>
                <div style={{display:"flex",gap:4,flexShrink:0}}>
                  {u.role==="tienda" && (u.device_token ? <Btn onClick={()=>liberarDispositivo(u)} variant="ghost" sm>📱 Liberar</Btn> : <Badge color={C.textMuted} sm>📱 Sin vincular</Badge>)}
                  <Btn onClick={()=>{setEditing(u.id);setEditVal({name:u.name,documento:u.documento,role:u.role,tienda_id:u.tienda_id||""});}} variant="ghost" sm>✏</Btn>
                  <Btn onClick={()=>{setCambiandoPass(u.id);setNuevaPass("");}} variant="ghost" sm>🔑</Btn>
                  <Btn onClick={()=>toggle(u)} variant={u.active?"danger":"success"} sm>{u.active?"✕":"✓"}</Btn>
                  <Btn onClick={()=>deleteUsuario(u.id)} variant="danger" sm title="Retirar (o eliminar si no tiene historial)">🗑</Btn>
                </div>
              </div>
            )}
            {editing!==u.id && cambiandoPass!==u.id && (
              <div style={{display:"flex",alignItems:"center",gap:8,marginTop:10,paddingTop:10,borderTop:`1px solid ${C.border}`,flexWrap:"wrap"}}>
                <span style={{fontFamily:font.body,fontSize:10,color:C.textMuted,textTransform:"uppercase",letterSpacing:"0.06em"}}>Contraseña actual</span>
                <span style={{fontFamily:font.mono,fontSize:12,color:C.text,letterSpacing:"0.05em"}}>{passVisible[u.id]?(u.password||"—"):"•".repeat(Math.max((u.password||"").length,6))}</span>
                <button onClick={()=>setPassVisible(p=>({...p,[u.id]:!p[u.id]}))} style={{background:"none",border:"none",cursor:"pointer",fontSize:11,color:C.goldLight,fontFamily:font.body,padding:0}}>{passVisible[u.id]?"🙈 Ocultar":"👁 Ver"}</button>
                <span style={{fontFamily:font.body,fontSize:10,color:C.textMuted,marginLeft:"auto"}}>{u.password_updated_at?`Actualizada: ${fmtFechaHora(u.password_updated_at)}`:"Sin registro de actualización"}</span>
              </div>
            )}
          </Card>
  );
  return (
    <div>
      <PageHeader title="Usuarios" subtitle={`${users.length} usuarios · solo visible para cuentas master · aquí se ve y controla la contraseña de todos`} action={
        <div style={{display:"flex",gap:8}}>
          <Btn onClick={traerFrescos} variant="ghost" sm disabled={sincronizando}>{sincronizando?"Actualizando...":"🔄 Actualizar"}</Btn>
          <Btn onClick={()=>{setShowForm(!showForm);setEditing(null);setCambiandoPass(null);}} sm>{showForm?"Cancelar":"+ Nuevo usuario"}</Btn>
        </div>
      } />
      {showForm&&(
        <Card glow style={{marginBottom:16}}>
          <div style={{fontFamily:font.body,fontSize:13,fontWeight:600,color:C.goldLight,marginBottom:14}}>Nuevo usuario</div>
          <Field label="Nombre completo" value={form.name} onChange={v=>setForm(f=>({...f,name:v}))} placeholder="Nombre Apellido" />
          <Field label="Usuario" value={form.documento} onChange={v=>setForm(f=>({...f,documento:v}))} placeholder="Usuario para ingresar" />
          <Field label="Tipo de usuario" value={form.role} onChange={v=>setForm(f=>({...f,role:v}))} options={roleOptions} />
          <div style={{fontFamily:font.body,fontSize:11,color:C.textMuted,marginTop:-10,marginBottom:12}}>🔎 {ROLE_PERMISOS[form.role]}</div>
          {form.role==="tienda" && <Field label="Tienda de esta cuenta" value={form.tienda_id} onChange={v=>setForm(f=>({...f,tienda_id:v}))} options={tiendaOptions} />}
          <div style={{fontFamily:font.body,fontSize:11,color:C.textMuted,marginBottom:12}}>💡 La contraseña inicial será el mismo usuario.</div>
          <Btn onClick={add} disabled={loading || (form.role==="tienda" && !form.tienda_id)} full>{loading?"Guardando...":"Crear usuario"}</Btn>
        </Card>
      )}
      <div style={{display:"flex",flexDirection:"column",gap:8}}>
        {ordenados.filter(u=>u.active!==false).map(tarjetaUsuario)}
        {ordenados.some(u=>u.active===false) && <SeccionRetirados n={ordenados.filter(u=>u.active===false).length} abierto={verRetirados} onToggle={()=>setVerRetirados(v=>!v)}/>}
        {verRetirados && ordenados.filter(u=>u.active===false).map(tarjetaUsuario)}
      </div>
    </div>
  );
}

// ── PERMISOS (Fases 1 y 2 — inventario, SOLO LECTURA) ──────────────────────────
// Tablero para master: qué puede hacer cada rol y cada persona HOY. Esta lista es una FOTO de las
// comprobaciones que están repartidas por todo este archivo (user.role==="master",
// esAdminDeVentas, puedeGestionarTurnos, soloLectura, etc.) — todavía NO manda sobre nada: ninguna
// pantalla lee de aquí. Si se cambia una comprobación en el código, hay que actualizar su fila.
// Fase 2: esta misma lista está sembrada en la tabla `permisos_roles` de Supabase
// (sql/permisos_fase2.sql) y el tablero avisa si la tabla y esta lista dejan de coincidir — si se
// agrega o cambia una fila aquí, hay que regenerar ese SQL. Desde la Fase 3 el código empieza a
// preguntarle a esas tablas con una sola función `puede(user, "permiso")`.
// Fase 4 (en curso): el tablero ya EDITA (interruptores por rol y excepciones por persona, con
// historial). Fase 3: los módulos preguntan con `puede()` (más abajo) y obedecen a la
// base: Caja, Ventas, Asistencia, Turnos, La Junta, Escuela y Cuenta. Falta solo la navegación
// entre áreas (puedeUsarAreas, areasPara), que sigue por rol. Para el resto esta lista sigue siendo una foto de sus comprobaciones.
// Cada permiso: `r` = qué rol lo tiene (1 = sí; un texto = sí, pero con esa condición).
